-- ============================================================
-- Quiz coverage pilot batch: 8 of the 20 zero-coverage DevOps
-- technologies (gitlab-ci, github-actions, fluxcd, tekton, ebpf,
-- harbor, keda, platform-engineering).
--
-- 5 questions per section x 4 sections (overview, fundamentals,
-- intermediate, advanced) x 8 technologies = 160 questions.
--
-- Every question is grounded directly in this session's own
-- content files (public/content/devops/<tech>/{overview,
-- fundamentals,intermediate,advanced}.md) -- specific commands,
-- CRD fields, table comparisons, and named mechanisms drawn
-- verbatim or near-verbatim from those files, not invented.
--
-- Applied via the confirmed real application method for this
-- engagement: @supabase/supabase-js with the service-role key,
-- upsert(rows, { onConflict: "academy_slug,technology_slug,
-- section_slug,question", ignoreDuplicates: true }) -- functionally
-- identical to this file's own ON CONFLICT ... DO NOTHING clause
-- below, for anyone running this .sql file directly instead
-- (e.g. via the Supabase SQL Editor or psql).
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- devops/gitlab-ci/overview ----------
('devops', 'gitlab-ci', 'overview', 'In a .gitlab-ci.yml pipeline with stages: [build, test, deploy], how do jobs within the same stage execute relative to each other?', '["Sequentially, in the order they appear in the file", "In parallel with each other", "Only one job per stage is allowed", "Randomly, GitLab picks the order"]', 1, 'Stages run sequentially (build, then test, then deploy), but jobs within the same stage run in parallel by default -- this is the base execution model before needs: is introduced to create finer-grained dependencies.', 'beginner'),
('devops', 'gitlab-ci', 'overview', 'Why does modern .gitlab-ci.yml use rules: instead of only:/except:?', '["rules: runs faster at pipeline execution time", "only: and except: are deprecated; rules: is the current, more flexible way to control when a job runs", "only: and except: are only valid for merge request pipelines", "rules: is required for the Security scanning templates specifically"]', 1, 'only:/except: are the deprecated legacy syntax. rules: is the current, more flexible mechanism for controlling job execution conditions, evaluated top to bottom.', 'beginner'),
('devops', 'gitlab-ci', 'overview', 'What does adding needs: [build-job] to a test job actually change, compared to the default stage-based ordering?', '["It has no effect if the jobs are already in sequential stages", "The test job starts as soon as build-job finishes, instead of waiting for every job in the build stage to complete -- turning the pipeline into a DAG", "It forces test to run before build-job, reversing the normal order", "It merges build-job and test into a single job"]', 1, 'needs: lets a job depend on specific other jobs rather than an entire stage, enabling a Directed Acyclic Graph (DAG) pipeline where independent jobs run in parallel regardless of stage position -- removing the stage-boundary bottleneck.', 'intermediate'),
('devops', 'gitlab-ci', 'overview', 'Which GitLab Runner executor runs each job in a fresh, clean container and is described as the most common choice?', '["Shell executor", "Docker executor", "Kubernetes executor", "VirtualBox executor"]', 1, 'The Docker executor runs each job in a fresh container -- clean and reproducible, and the most common choice. Shell runs directly on the runner VM (fast but environment pollutes between jobs); Kubernetes runs each job as a pod (autoscales to zero, best for production).', 'intermediate'),
('devops', 'gitlab-ci', 'overview', 'What is described as GitLab CI/CD''s biggest advantage over Jenkins?', '["Faster job execution speed", "Built-in security scanning (SAST, container scanning, dependency scanning, secret detection) via included templates, with results in the MR widget", "Lower cost per pipeline minute", "Support for more programming languages"]', 1, 'GitLab has built-in security scanning as one of its biggest advantages over Jenkins -- including GitLab-provided templates adds SAST, container scanning, dependency scanning, and secret detection in minutes, with results appearing directly in the Merge Request security widget.', 'beginner'),

-- ---------- devops/gitlab-ci/fundamentals ----------
('devops', 'gitlab-ci', 'fundamentals', 'Before pushing a .gitlab-ci.yml change, what is the recommended way to validate it, per the CI Lint API example?', '["There is no way to validate a pipeline before pushing", "POST the file content to the project''s /api/v4/projects/:id/ci/lint endpoint, or use the Pipeline Editor''s Lint tab", "Push to a throwaway branch and see if the pipeline fails", "Only GitLab support can validate pipeline syntax"]', 1, 'The CI Lint API (curl POST to /ci/lint) or the built-in Pipeline Editor''s Lint tab validates a .gitlab-ci.yml before pushing, catching syntax errors early rather than discovering them only after a pipeline run fails.', 'beginner'),
('devops', 'gitlab-ci', 'fundamentals', 'What is the key functional difference between artifacts and cache in GitLab CI?', '["They are exactly equivalent, just different keywords", "Artifacts pass this run''s outputs forward between jobs in the same pipeline (reliably present); cache persists dependencies across separate pipeline runs to speed up builds (not guaranteed to survive)", "Cache is for files, artifacts are only for text output", "Artifacts only work with the Kubernetes executor"]', 1, 'Artifacts are for passing this pipeline run''s actual outputs forward between jobs -- reliably available to the pipeline that created them. Cache is for avoiding redundant work across separate runs (like node_modules) and can be evicted, so it is not guaranteed to be present.', 'intermediate'),
('devops', 'gitlab-ci', 'fundamentals', 'In the example test-fast job with needs: [build-job], what does this achieve compared to the default stage-based dependency?', '["It waits for every job in the build stage to finish before starting", "It starts as soon as build-job specifically finishes, without waiting for other build-stage jobs", "It skips the build stage entirely", "It requires build-job to fail before test-fast can run"]', 1, 'needs: lets a job run as soon as its specific declared dependencies finish, instead of waiting for the entire previous stage -- this is the DAG mechanism that removes unnecessary stage-boundary waiting.', 'intermediate'),
('devops', 'gitlab-ci', 'fundamentals', 'Per the Runners comparison table, what is a real drawback of the self-hosted Kubernetes executor?', '["It cannot run Docker builds at all", "Pod startup time (10-30 seconds) before a job actually begins", "It has a hard limit of 400 minutes per month", "It requires a public runner, a security concern for sensitive code"]', 1, 'The Kubernetes executor''s con is pod startup time (10-30 sec) -- each job needs a new pod scheduled and started before work begins, unlike the Shell executor which has no such startup delay (at the cost of build pollution between jobs).', 'intermediate'),
('devops', 'gitlab-ci', 'fundamentals', 'What is the functional difference between marking a CI/CD variable Protected versus Masked?', '["They do the same thing; Protected is just the newer name", "Protected restricts the variable to protected branches only; Masked hides its value in job logs -- both are independent settings", "Masked variables cannot be used in scripts at all", "Protected variables are automatically also Masked"]', 1, 'Protected restricts a variable to protected branches (main, release branches) only; Masked hides its value in job logs. They are independent settings, and both should be enabled by default for any real secret.', 'intermediate'),

-- ---------- devops/gitlab-ci/intermediate ----------
('devops', 'gitlab-ci', 'intermediate', 'In a child-pipeline trigger job, what does strategy: depend actually change about the parent pipeline''s reported status?', '["It has no effect on status reporting", "Without it, the parent reports success the moment it triggers the child, regardless of the child''s later outcome; with it, the parent pipeline waits on and reflects the child pipeline''s actual status", "It causes the parent pipeline to fail immediately if a child pipeline is used at all", "It only affects how logs are displayed, not pipeline status"]', 1, 'strategy: depend makes the parent pipeline wait on and reflect the child pipeline''s actual result. Without it, the parent reports success the instant it triggers the child, producing a misleadingly green parent for a deploy that actually broke later.', 'intermediate'),
('devops', 'gitlab-ci', 'intermediate', 'What problem do Merge Trains specifically solve for a high-velocity repository?', '["They prevent any two people from working on the same file", "Two MRs that each individually pass CI but conflict when combined get caught by the train''s speculative merge-and-test step, before they actually land on main together", "They automatically write commit messages for merged branches", "They replace the need for code review entirely"]', 1, 'A merge train queues approved MRs and tests each one as if the previous ones in the queue had already merged -- catching integration conflicts between queued MRs before they actually merge, not after both are already on main.', 'intermediate'),
('devops', 'gitlab-ci', 'intermediate', 'In the Review App example, what does wiring on_stop: stop-review-app actually prevent?', '["It prevents the review app from ever being created", "Review-app namespaces accumulating indefinitely, since without a dedicated cleanup job every MR would leave behind a running environment nobody tears down", "It prevents developers from viewing the review app URL", "It is required for the review app to receive traffic at all"]', 1, 'on_stop wiring a dedicated cleanup job (stop-review-app) is what prevents review-app namespaces from piling up over time -- without it, every merge request leaves behind a running environment that nobody explicitly tears down.', 'intermediate'),
('devops', 'gitlab-ci', 'intermediate', 'A parallel: matrix job with NODE_VERSION: ["18","20","22"] and OS: ["ubuntu","alpine"] generates how many parallel jobs from that one job definition?', '["2 jobs", "3 jobs", "5 jobs", "6 jobs"]', 3, '3 Node versions times 2 OS images = 6 parallel jobs generated from a single job definition -- the matrix strategy tests every combination without hand-writing one job per combination.', 'intermediate'),
('devops', 'gitlab-ci', 'intermediate', 'Why does scoping a CI/CD variable to a specific environment (e.g. staging) matter, beyond just Protected/Masked flags?', '["Environment scoping is purely cosmetic and has no security effect", "An unscoped DEPLOY_TOKEN variable is technically available to every environment''s jobs, meaning a staging deploy job could access production credentials if the pipeline definition ever changes; environment scoping makes that structurally impossible", "It is required for the pipeline to run at all", "It only affects which branch can trigger the pipeline"]', 1, 'Beyond Protected/Masked, environment-scoped variables prevent a single unscoped variable (like DEPLOY_TOKEN) from being technically reachable by every environment''s jobs -- without scoping, a staging job could access production credentials if the pipeline definition ever changed, relying on job authors being careful rather than a structural guarantee.', 'advanced'),

-- ---------- devops/gitlab-ci/advanced ----------
('devops', 'gitlab-ci', 'advanced', 'What does a multi-project trigger job with strategy: depend, targeting project: mygroup/consuming-service, actually enable?', '["It only works within a single project, not across repositories", "A microservices architecture where a shared library change needs to trigger downstream builds in a different project, with the parent pipeline''s status reflecting the downstream pipeline''s actual result", "It automatically merges the two projects into one repository", "It disables the downstream project''s own pipeline permanently"]', 1, 'Multi-project pipelines let a shared-library change trigger downstream builds in a genuinely different project, with strategy: depend making the parent pipeline reflect the downstream pipeline''s actual result -- the mechanism a monorepo would handle differently but a multi-repo architecture needs explicit wiring for.', 'advanced'),
('devops', 'gitlab-ci', 'advanced', 'What is the concrete purpose of setting a node_selector for CI workloads on a Kubernetes-executor runner fleet?', '["It makes CI jobs run faster by using more CPU cores automatically", "It dedicates specific cluster nodes to CI workloads, preventing a burst of CI jobs from starving production workloads of the same underlying compute", "It is required for the Kubernetes executor to function at all", "It disables autoscaling for the CI node pool"]', 1, 'Dedicating a node pool specifically to CI workloads (via node_selector plus a matching cluster autoscaler node group) is the concrete mechanism that prevents a burst of CI jobs from starving production workloads for cluster resources -- the two otherwise compete for the same underlying compute.', 'advanced'),
('devops', 'gitlab-ci', 'advanced', 'What is the actual discipline recommended for writing needs: lists in a large, dozens-of-jobs pipeline?', '["List every job that logically comes before this one, to be safe", "List only the minimum real dependencies -- an unnecessarily broad needs: list re-introduces the same serialization a DAG pipeline exists to remove", "Never use needs: in pipelines with more than 10 jobs", "Always list at least 3 dependencies per job for reliability"]', 1, 'needs: should list only the minimum real dependencies, not "everything logically before this stage." A single job with an unusually large number of needs: pointing to it becomes a serialization bottleneck regardless of how well everything else is parallelized.', 'advanced'),
('devops', 'gitlab-ci', 'advanced', 'How does including a versioned CI/CD Catalog component (e.g. @2.1.0) differ structurally from a plain include: of a shared template?', '["There is no structural difference, only naming convention differs", "A breaking change to a versioned component bumps its major version, so consuming pipelines keep working on their pinned version until they deliberately opt into an upgrade -- a shared include: template change can silently break every pipeline including it simultaneously", "Catalog components cannot accept input parameters, unlike plain includes", "Versioned components only work for security-scanning pipelines"]', 1, 'The CI/CD Catalog''s semantic versioning is the structural improvement -- a breaking change to a component bumps its major version, and pipelines pinned to an older version keep working until they deliberately upgrade, unlike a shared include: template change that can silently break every consuming pipeline at once.', 'advanced'),
('devops', 'gitlab-ci', 'advanced', 'In a self-hosted GitLab HA deployment, what specific operational risk does Gitaly replication lag introduce during a primary-node failure?', '["GitLab becomes completely unavailable during any failover", "A failover can briefly serve slightly stale repository data -- a real tradeoff between failover speed and consistency that a single-node deployment never faces, since it can''t fail over at all", "Gitaly replication lag only affects CI/CD pipelines, never Git operations", "It causes permanent, unrecoverable data loss on every failover"]', 1, 'The specific risk worth naming is that Gitaly replication lag during a primary-node failure can mean a failover briefly serves slightly stale repository data -- a real, non-obvious tradeoff between failover speed and consistency that a single-node deployment never has to make.', 'advanced'),

-- ---------- devops/github-actions/overview ----------
('devops', 'github-actions', 'overview', 'By default, how do jobs within a single GitHub Actions workflow run relative to each other?', '["Always sequentially, one after another", "In parallel, unless a needs: dependency is declared between them", "Only one job can exist per workflow file", "In the order GitHub''s scheduler randomly assigns"]', 1, 'Jobs run in parallel by default; needs: is used to create explicit dependencies between them, same conceptual model as GitLab CI''s stage-parallelism but expressed per-job rather than per-stage.', 'beginner'),
('devops', 'github-actions', 'overview', 'Why should third-party Actions be pinned to a specific commit SHA rather than a mutable tag like @master?', '["SHA pinning makes workflows run measurably faster", "A tag is mutable and a compromised maintainer account could push a malicious update to an existing tag; a SHA pin guarantees the exact code that runs never changes underneath you", "Actions referenced by SHA don''t count against the free-tier minute limit", "GitHub requires SHA pinning for all workflows by policy"]', 1, 'Always pin actions to a SHA or version tag (not @master) for security -- tags are mutable, so a compromised action maintainer account could push a malicious update to an existing tag, while a SHA pin is immutable.', 'beginner'),
('devops', 'github-actions', 'overview', 'What does a matrix strategy with node-version: [18, 20, 22] actually produce?', '["One job that installs all three Node versions sequentially", "The same job run in parallel with each parameter value -- e.g. testing on Node 18, 20, and 22 simultaneously", "Three separate workflow files, one per version", "A single job that fails if any version is unsupported"]', 1, 'Matrix strategy runs the same job with different parameters in parallel -- e.g. test on Node 18, 20, 22 simultaneously, generating one parallel job run per combination from a single job definition.', 'beginner'),
('devops', 'github-actions', 'overview', 'What does OIDC federation let a GitHub Actions workflow do that storing static cloud credentials as Secrets does not?', '["It makes cloud API calls faster", "The workflow requests a short-lived token directly from the cloud provider at run time, so no long-lived cloud credentials need to be stored in GitHub Secrets at all", "It removes the need for a runner entirely", "It only works for AWS, not Azure or GCP"]', 1, 'OIDC is the modern approach -- no long-lived cloud credentials needed. The workflow requests a short-lived token from the cloud provider directly via OIDC federation, rather than reading a static access key stored as a Secret.', 'advanced'),
('devops', 'github-actions', 'overview', 'In the Production Example workflow, why do the test and scan jobs run without a needs: dependency between them?', '["GitHub Actions requires every job to have at least one dependency", "They are independent and can run in parallel -- only deploy, which needs both, waits, so total pipeline time is max(test, scan) rather than test + scan", "test and scan cannot both use the same runner simultaneously otherwise", "It is a mistake in the example; they should depend on each other"]', 1, 'test and scan run in parallel specifically because neither needs: the other -- only deploy declares needs: [test, scan], so total pipeline time is bounded by the slower of the two rather than their sum.', 'intermediate'),

-- ---------- devops/github-actions/fundamentals ----------
('devops', 'github-actions', 'fundamentals', 'What is the correct hierarchy of GitHub Actions concepts, from triggering to individual execution?', '["Step triggers a Job, which triggers a Workflow, which triggers an Event", "An Event happens, which triggers a Workflow, which runs Jobs in parallel, each of which runs Steps in sequence", "A Runner triggers an Action, which triggers a Job", "Workflows and Jobs are the same concept with different names"]', 1, 'The core concept chain is: an Event happens (push to main) -> a Workflow triggers -> Jobs run in parallel on separate VMs -> each Job has Steps that run in sequence.', 'beginner'),
('devops', 'github-actions', 'fundamentals', 'Per the three-tier secrets table, what distinguishes Environment secrets from Repository secrets?', '["Environment secrets are visible to every workflow in the repo, same as Repository secrets", "Environment secrets are accessible only to jobs using that specific environment, unlike Repository secrets which are accessible to all workflows in the repo", "Environment secrets cannot be masked in logs", "Environment secrets only work for public repositories"]', 1, 'Repository secrets are accessible to all workflows in the repo; Environment secrets are only accessible to jobs using that specific environment -- useful for keeping production values separate from staging values within the same pipeline definition.', 'intermediate'),
('devops', 'github-actions', 'fundamentals', 'In the reusable workflow example, what keyword lets one workflow be called from another with input parameters?', '["workflow_dispatch", "workflow_call", "workflow_run", "on: reusable"]', 1, 'on: workflow_call is the trigger that makes a workflow reusable -- callable from another workflow with a uses: reference and inputs, avoiding duplicated deploy-pattern YAML across many services.', 'intermediate'),
('devops', 'github-actions', 'fundamentals', 'Per the troubleshooting table, "works locally, fails in CI" is most commonly caused by what?', '["A GitHub outage", "A tool used locally isn''t installed on the runner, requiring an explicit setup step in the workflow", "The workflow YAML has a syntax error", "The developer''s local machine has a different operating system"]', 1, 'The troubleshooting table attributes "works locally, fails in CI" to a tool not installed on the runner -- the fix is adding explicit setup steps for that tool, since the runner starts from a clean environment without whatever was pre-installed on a developer''s machine.', 'intermediate'),
('devops', 'github-actions', 'fundamentals', 'Why does using a quality job and a security job in parallel (both required before build starts) matter for total pipeline time?', '["It doesn''t matter; GitHub Actions runs everything sequentially regardless", "Since neither depends on the other, they run simultaneously rather than one after the other, and needs: [quality, security] on the build job is what creates that explicit dependency graph", "Parallel jobs share the same runner and therefore run slower", "Only one of the two jobs can actually run per workflow trigger"]', 1, 'The quality and security jobs run in parallel because neither is declared as depending on the other; needs: [quality, security] on the build job is what creates the explicit dependency graph forcing build to wait for both, without forcing quality and security to wait on each other.', 'intermediate'),

-- ---------- devops/github-actions/intermediate ----------
('devops', 'github-actions', 'intermediate', 'Inside a composite action''s run: steps, why must shell: bash be specified explicitly on every step?', '["It is optional and only affects log formatting", "Unlike a normal workflow step, composite actions don''t inherit a default shell -- omitting shell: is a common, confusing first-time error", "shell: bash is required only when running on Windows runners", "Composite actions execute steps in parallel, not sequentially, so shell: coordinates ordering"]', 1, 'shell: bash is required on every run: step inside a composite action specifically because composite actions, unlike normal workflow steps, don''t inherit a default shell -- omitting it is called out as a common, confusing first-time error.', 'intermediate'),
('devops', 'github-actions', 'intermediate', 'What is the current, non-deprecated mechanism for a step to set an output another job can consume?', '["The ::set-output:: workflow command", "Writing to the $GITHUB_OUTPUT environment file (e.g. echo \"tag=value\" >> \"$GITHUB_OUTPUT\")", "Writing directly to a file named output.txt in the repo root", "Job outputs cannot be passed between jobs in GitHub Actions"]', 1, '>> "$GITHUB_OUTPUT" is the current mechanism for setting a step output -- the older ::set-output:: workflow command syntax is deprecated, which matters since older workflow examples online still use it.', 'intermediate'),
('devops', 'github-actions', 'intermediate', 'For a deploy workflow specifically, why might cancel-in-progress: true under concurrency: be deliberately set to false?', '["false is required syntax and true is never valid", "Cancelling a deploy job mid-flight can leave infrastructure in a partially-applied state, so deploy workflows often queue instead of cancel, while CI/test workflows can safely cancel superseded runs", "concurrency: only applies to test workflows, never deploy workflows", "Setting it to false disables the workflow entirely"]', 1, 'cancel-in-progress: true is often set for CI/test workflows (safe to cancel superseded work) but deliberately false for deploy workflows, since cancelling a deploy mid-flight can leave infrastructure in a partially-applied, dangerous state.', 'advanced'),
('devops', 'github-actions', 'intermediate', 'What is required for a reusable workflow to actually receive a secret from the calling workflow?', '["Secrets automatically flow into any reusable workflow that is called", "The calling workflow must explicitly pass the secret under a secrets: block when invoking the reusable workflow with uses:", "Reusable workflows can never access secrets under any configuration", "The secret must be renamed to match the reusable workflow''s filename"]', 1, 'Secrets don''t automatically flow into a reusable workflow just because it''s called -- the calling workflow must explicitly pass them under a secrets: block, making the secret-passing contract visible rather than implicit.', 'intermediate'),
('devops', 'github-actions', 'intermediate', 'Beyond a bare environment: production declaration, what actually makes an environment function as an approval gate?', '["Naming the environment production automatically triggers manual approval", "Protection rules (required reviewers, wait timer) configured per-environment in repo settings -- without them, the job pauses in Waiting only if a rule is actually attached", "Every GitHub Actions job automatically requires approval regardless of environment", "Protection rules only apply to self-hosted runners"]', 1, 'Environment protection rules (required reviewers, wait timer, branch restrictions), configured per-environment in Settings > Environments, are what turn a bare environment: declaration into an actual, enforceable approval gate -- not the environment name alone.', 'intermediate'),

-- ---------- devops/github-actions/advanced ----------
('devops', 'github-actions', 'advanced', 'What is the specific security risk of running self-hosted runners on a public repository?', '["Self-hosted runners are always slower than GitHub-hosted ones", "A malicious pull request''s workflow can run arbitrary code on infrastructure the org controls, unlike ephemeral, isolated GitHub-hosted runners", "Self-hosted runners cannot use the actions/checkout action", "Public repos are not allowed to use self-hosted runners at all"]', 1, 'Self-hosted runners on a public repo are a real security exposure -- a malicious PR''s workflow can run arbitrary code on org-controlled infrastructure, unlike GitHub-hosted runners which are ephemeral and isolated per-run by design.', 'advanced'),
('devops', 'github-actions', 'advanced', 'Why might scoping an IAM trust policy''s sub claim to a specific environment (e.g. repo:org/repo:environment:production) be tighter than scoping to a branch ref?', '["Environment scoping and branch scoping provide identical security", "Environment scoping means the role can only be assumed by a workflow run actually deploying through that protected environment, including its required-reviewer gate -- not just any workflow running on that branch", "Branch scoping is more secure because branches cannot be deleted", "Environment-based scoping is not supported by any cloud provider''s OIDC integration"]', 1, 'Scoping to environment:production specifically means the role can only be assumed by a workflow run actually deploying through the protected production environment (including its approval gate) -- a materially tighter blast radius than scoping to a branch ref alone, which any workflow on that branch could satisfy.', 'advanced'),
('devops', 'github-actions', 'advanced', 'What does actions/attest-build-provenance generate, and what is it the GitHub-native equivalent of?', '["A code coverage report; equivalent to a linter", "A signed attestation linking a built artifact back to the specific workflow run, commit, and inputs that produced it -- the GitHub Actions equivalent of Tekton Chains", "A performance benchmark; equivalent to a load-testing tool", "A dependency vulnerability scan; equivalent to Dependabot"]', 1, 'actions/attest-build-provenance generates a signed attestation linking a built artifact back to the specific workflow run, commit, and inputs that produced it -- described as the GitHub Actions equivalent of Tekton Chains, without needing a separate supply-chain-security tool bolted on.', 'advanced'),
('devops', 'github-actions', 'advanced', 'Why is granting id-token: write permission specifically worth auditing across an organization''s workflows?', '["It has no security implications, only cost implications", "id-token: write is specifically what enables OIDC cloud authentication, and shouldn''t be granted to workflows that don''t need to authenticate to a cloud provider", "It is required for every workflow to check out code", "It only affects workflow run time limits"]', 1, 'id-token: write is specifically what enables OIDC cloud authentication -- auditing which workflows have it is a direct, concrete least-privilege check, since it shouldn''t be granted to workflows that don''t actually need to authenticate to a cloud provider.', 'advanced'),
('devops', 'github-actions', 'advanced', 'For larger GitHub-hosted runners (e.g. ubuntu-latest-8-cores), why is "bigger is always better" not a safe assumption?', '["Larger runners are actually slower than standard runners", "A build that is I/O-bound rather than CPU-bound may see little speedup from more cores while still paying the larger runner''s higher per-minute rate", "Larger runners cannot run Docker builds", "Larger runners are only available for private repositories"]', 1, 'The cost/speed tradeoff is worth modeling explicitly -- an I/O-bound build may see little speedup from more CPU cores while still paying the larger runner''s premium per-minute rate, so bigger is not automatically better.', 'advanced'),

-- ---------- devops/fluxcd/overview ----------
('devops', 'fluxcd', 'overview', 'What is the key architectural difference between FluxCD and ArgoCD, per the direct comparison?', '["FluxCD has a rich UI while ArgoCD is CLI-only", "FluxCD has no UI at all -- everything is CRDs managed via CLI or kubectl; ArgoCD has a rich UI for visualising application state", "They are functionally identical with no real differences", "ArgoCD cannot manage Helm charts, only FluxCD can"]', 1, 'ArgoCD has a rich UI for visualising application state; FluxCD has no UI -- everything is CRDs managed via CLI or kubectl. FluxCD is preferred by platform teams wanting pure CLI-driven GitOps with no web UI to maintain.', 'beginner'),
('devops', 'fluxcd', 'overview', 'What does the GitRepository CRD specifically do in FluxCD''s reconciliation loop?', '["It applies Kubernetes manifests directly to the cluster", "It tells Flux where to watch (a Git repo, branch, and polling interval) -- it does not itself apply anything", "It manages Helm chart installations", "It defines RBAC permissions for tenant isolation"]', 1, 'GitRepository tells Flux where to watch -- a Git URL, branch, and interval. Kustomization is the separate CRD that tells Flux what path to apply from that repo; GitRepository only watches.', 'beginner'),
('devops', 'fluxcd', 'overview', 'What does prune: true do on a Kustomization resource?', '["It compresses the Git repository to save space", "It deletes cluster resources that have been removed from Git, keeping the cluster state matching Git exactly", "It prevents any resources from ever being deleted", "It removes old container image tags from the registry"]', 1, 'prune: true tells the Kustomization to delete resources removed from Git -- this is part of what makes GitOps reconciliation bidirectional (the cluster matches Git, including deletions), not just additive.', 'intermediate'),
('devops', 'fluxcd', 'overview', 'Per FluxCD''s multi-tenancy model, what specifically prevents Team A''s Kustomization from deploying into Team B''s namespace?', '["FluxCD has a hardcoded rule blocking cross-namespace deploys", "Each team''s Kustomization runs with a ServiceAccount scoped to their own namespace via serviceAccountName:, rather than Flux''s own cluster-wide permissions", "Teams cannot have more than one Kustomization each", "Namespace names are cryptographically signed per team"]', 1, 'Each tenant''s Kustomization sets serviceAccountName: to a ServiceAccount scoped to their own namespace -- Flux then reconciles using that tenant''s RBAC specifically, not Flux''s own cluster-wide permissions, which is what makes cross-team isolation real rather than aspirational.', 'advanced'),
('devops', 'fluxcd', 'overview', 'What is described as FluxCD''s "killer feature" relative to ArgoCD in the direct comparison table?', '["A built-in web dashboard", "Better native multi-tenancy support", "Support for Docker Compose files", "Automatic rollback on every deploy"]', 1, 'FluxCD has better multi-tenancy support natively, per the direct comparison -- this is presented as a core differentiator, alongside its no-UI, pure-CRD-driven design that platform teams doing CLI-only workflows prefer.', 'intermediate'),

-- ---------- devops/fluxcd/fundamentals ----------
('devops', 'fluxcd', 'fundamentals', 'In FluxCD''s pull model, which system initiates contact between the cluster and the Git repository?', '["An external CI/CD pipeline pushes changes into the cluster", "The cluster itself -- agents inside the cluster pull the desired state from Git, and Git credentials live as Kubernetes secrets inside the cluster", "The Kubernetes API server pushes state out to Git", "A separate, externally-hosted Flux control plane pushes changes in"]', 1, 'Flux uses a pull model -- agents inside the cluster pull from Git, and the cluster never exposes its API server to external systems for this purpose. Git credentials are stored as Kubernetes secrets inside the cluster, not held by an external CI system.', 'beginner'),
('devops', 'fluxcd', 'fundamentals', 'Why is the pull model described as more secure than a traditional push-based CI/CD deployment?', '["Pull-based deployments are always faster than push-based ones", "The push model requires the cluster API server to be reachable from outside and requires cluster credentials to be stored in the CI system; the pull model needs neither, shrinking the attack surface", "Pull-based deployments don''t require any authentication at all", "Push-based deployments cannot use HTTPS"]', 1, 'The push model needs cluster credentials stored in the CI/CD pipeline and a reachable API server; the pull model has agents inside the cluster watching Git, with the cluster never exposing its API externally for this purpose -- a much smaller attack surface.', 'intermediate'),
('devops', 'fluxcd', 'fundamentals', 'What does the flux bootstrap command accomplish, beyond just installing Flux into the cluster?', '["It only installs Flux; Git configuration must be committed manually afterward", "It installs Flux controllers into the cluster AND commits Flux''s own configuration to the Git repository, so Flux subsequently manages itself via GitOps", "It creates a new Kubernetes cluster from scratch", "It only works for GitLab, not GitHub"]', 1, 'Bootstrap does two things at once: installs Flux controllers in the cluster, and commits the Flux configuration to the Git repository -- Flux then manages itself, updating its own controllers when the Git-stored config changes.', 'intermediate'),
('devops', 'fluxcd', 'fundamentals', 'Per the Core Flux CRDs table, what does ImageUpdateAutomation specifically do?', '["It watches a container registry for new image tags", "It commits the new image tag back to Git automatically, closing the loop after a new image is detected", "It selects which image tag qualifies via semver or regex", "It defines a Helm chart repository to watch"]', 1, 'ImageUpdateAutomation commits the new image tag back to Git automatically -- it is the final step of the three-CRD image automation chain (ImageRepository watches, ImagePolicy selects, ImageUpdateAutomation commits back to Git).', 'intermediate'),
('devops', 'fluxcd', 'fundamentals', 'What does Kustomize let you do without needing Go template syntax or placeholders?', '["Write custom Helm charts from scratch", "Customize Kubernetes YAML for different environments using base manifests plus per-environment overlays that patch specific fields", "Automatically generate Dockerfiles for any application", "Replace the need for a container registry entirely"]', 1, 'Kustomize lets you customize Kubernetes YAML for different environments without templates or placeholders -- define base manifests once, then create per-environment overlays that patch specific fields using plain, structured YAML patches.', 'beginner'),

-- ---------- devops/fluxcd/intermediate ----------
('devops', 'fluxcd', 'intermediate', 'Why does scoping an Alert''s eventSources to a specific namespace and eventSeverity: error matter, rather than alerting on every reconciliation event?', '["It has no practical effect, both configurations behave identically", "Alerting on every successful sync in a cluster reconciling every few minutes produces channel noise nobody reads -- scoping to errors and a namespace keeps alerts genuinely actionable", "eventSeverity: error is required syntax with no functional meaning", "It reduces the number of GitRepository resources needed"]', 1, 'Scoping eventSources to a namespace and eventSeverity: error (rather than every event including successes) is what keeps notifications useful rather than noisy -- alerting on every successful sync in a frequently-reconciling cluster produces channel noise nobody actually reads.', 'intermediate'),
('devops', 'fluxcd', 'intermediate', 'What problem does postBuild.substitute solve for a Kustomization applied across multiple environments?', '["It encrypts sensitive values before they reach the cluster", "It injects environment-specific values (replica count, environment name) into the Kustomization''s output after Kustomize itself has run, keeping the base manifests identical across environments", "It automatically scales the Kustomization''s target Deployment", "It converts Helm charts into plain Kustomize manifests"]', 1, 'postBuild.substitute (or substituteFrom for larger variable sets) injects values into a Kustomization''s output after Kustomize has run -- keeping base manifests genuinely identical across environments, with only the Kustomization resource itself differing per environment.', 'intermediate'),
('devops', 'fluxcd', 'intermediate', 'In the full image automation chain, what specifically does the semver range on ImagePolicy prevent?', '["It prevents any image from ever being deployed automatically", "A runaway auto-deploy of an unintended tag -- without the range constraint, image automation would deploy any new tag pushed to the registry, including an accidental major-version bump", "It prevents ImageRepository from watching the registry at all", "It is only a documentation field with no enforcement effect"]', 1, 'The semver range constraint on ImagePolicy (e.g. ">=1.0.0 <2.0.0") is what prevents a runaway auto-deploy -- without it, image automation would happily deploy any new tag pushed to the registry, including an accidental major-version bump never meant to reach production automatically.', 'advanced'),
('devops', 'fluxcd', 'intermediate', 'What happens if two Kustomizations have a real dependency relationship but dependsOn is not set between them?', '["Flux automatically infers the dependency from manifest content", "Both Kustomizations reconcile independently and roughly in parallel, which can be a silent source of intermittent failures if one genuinely needs resources the other creates", "The Kustomization without dependsOn fails to apply entirely", "Flux refuses to start until dependsOn is explicitly set on every Kustomization"]', 1, 'Without dependsOn, both Kustomizations reconcile independently and roughly in parallel -- fine when there''s no real ordering requirement, but a silent source of intermittent failures when one genuinely depends on resources the other creates (like a CRD or namespace).', 'advanced'),
('devops', 'fluxcd', 'intermediate', 'What does the Provider and Alert CRD pairing play the same role as, in FluxCD''s overall architecture?', '["The same role as the kustomize-controller applying manifests", "The same role as notification-controller in the overall architecture -- wiring reconciliation events to external systems like Slack", "The same role as GitRepository watching source changes", "The same role as helm-controller managing HelmReleases"]', 1, 'Provider and Alert CRDs configure declaratively the same role notification-controller plays in the overall architecture -- wiring reconciliation events (success, failure) to external systems like Slack, rather than requiring a UI to configure.', 'intermediate'),

-- ---------- devops/fluxcd/advanced ----------
('devops', 'fluxcd', 'advanced', 'At scale (dozens of tenants on one cluster), what does label-based sharding actually address?', '["It encrypts tenant data separately per shard", "It prevents one enormous shared kustomize-controller instance from reconciling every tenant''s resources serially and becoming a bottleneck as tenant count grows", "It automatically creates new tenants without manual configuration", "It replaces the need for per-tenant ServiceAccounts"]', 1, 'Sharding assigns specific controllers to specific tenant workloads via label-based routing, so one enormous shared kustomize-controller instance isn''t reconciling every tenant''s resources serially -- reducing reconciliation contention as tenant count grows.', 'advanced'),
('devops', 'fluxcd', 'advanced', 'Why does the metric gotk_reconcile_condition{type="Ready", status="False"} == 1 matter for monitoring Flux itself?', '["It only measures CPU usage of the Flux controllers", "It is the metric-based equivalent of the notification-controller alert -- useful for catching Kustomizations that haven''t successfully reconciled recently when Prometheus is already the standard alerting path", "It measures how many Git commits have been made", "It only applies to HelmRelease resources, not Kustomizations"]', 1, 'This PromQL query is described as the metric-based equivalent of the notification-controller alert covered in Intermediate -- useful specifically when Prometheus is already the team''s standard alerting path, alerting on Kustomizations that have not successfully reconciled.', 'advanced'),
('devops', 'fluxcd', 'advanced', 'For a GitOps-managed cluster, what does the disaster recovery story NOT automatically cover, even though configuration recovery is largely "bootstrap Flux against the same Git repo"?', '["Kubernetes namespace names", "Persistent volume contents and database state -- data still needs its own separate backup strategy", "The GitRepository CRD itself", "HelmRelease CRDs specifically"]', 1, 'Since the cluster''s desired configuration state already lives in Git, recovering configuration is largely "provision a new cluster, bootstrap Flux against the same repo." This does NOT cover data -- persistent volume contents and database state still need their own separate backup strategy.', 'advanced'),
('devops', 'fluxcd', 'advanced', 'What does Flagger add on top of FluxCD''s own apply-and-reconcile behavior?', '["Flagger replaces FluxCD entirely for GitOps deployments", "Gradual, metric-driven canary traffic shifting with automatic rollback if a defined success-rate metric breaches threshold -- FluxCD alone applies changes but does not do gradual traffic shifting", "Flagger encrypts secrets stored in Git", "Flagger is required for FluxCD to support Helm charts at all"]', 1, 'FluxCD alone does apply-and-reconcile, not gradual traffic shifting. Flagger integrates to automate the canary process itself -- shifting traffic incrementally while checking a defined metric, and rolling back automatically if that metric breaches threshold at any step.', 'advanced'),
('devops', 'fluxcd', 'advanced', 'Why should tenant bootstrapping itself be GitOps-managed and repeatable at real multi-tenant scale, rather than a manual per-tenant setup?', '["Manual setup is actually faster for onboarding new tenants", "A repeatable, templated bootstrap (generating a new tenant''s GitRepository, ServiceAccount, RoleBinding, and initial Kustomization from one input) keeps onboarding consistent and auditable as tenant count grows", "Kubernetes does not allow manual resource creation for multi-tenant clusters", "Tenant bootstrapping cannot be automated in FluxCD"]', 1, 'At real scale (dozens of tenants), tenant bootstrapping should itself be GitOps-managed and repeatable -- a template generating a new tenant''s GitRepository, ServiceAccount, RoleBinding, and initial Kustomization from a single input keeps onboarding consistent and auditable, rather than an ad hoc manual process per tenant.', 'advanced'),

-- ---------- devops/tekton/overview ----------
('devops', 'tekton', 'overview', 'What does it mean that Tekton is described as having "no central server to manage"?', '["Tekton runs entirely outside of Kubernetes on dedicated hardware", "Every pipeline step runs as a Kubernetes pod, and the pipeline definitions themselves are Kubernetes CRDs -- there is no separate CI server process to patch or scale", "Tekton pipelines cannot be triggered automatically", "Tekton requires a paid central coordination service"]', 1, 'Tekton is a Kubernetes-native CI/CD framework where each pipeline step runs as a K8s pod, with no central server to manage -- everything is CRD-based (Task, Pipeline, PipelineRun, Trigger), unlike Jenkins which needs a separate server process.', 'beginner'),
('devops', 'tekton', 'overview', 'What is the relationship between a Task and a Pipeline in Tekton?', '["They are the same object with different names", "A Task is a single step (like a Job); a Pipeline chains multiple Tasks together with parameters passing between them", "A Pipeline is a single step inside a Task", "Pipelines can only contain exactly one Task"]', 1, 'A Task is like a Job in Kubernetes -- it runs one or more steps in containers. A Pipeline chains Tasks with parameters passing between them, representing the higher-level workflow.', 'beginner'),
('devops', 'tekton', 'overview', 'What is the specific purpose of a Workspace in a Tekton Pipeline?', '["It stores pipeline configuration as YAML", "It provides shared filesystem so one Task (e.g. git-clone) can write files another Task (e.g. build) later reads", "It defines which namespace the Pipeline runs in", "It is only used for storing container images"]', 1, 'Workspaces provide shared filesystem between Tasks -- git-clone writes code to a workspace, and the build Task reads from that same workspace. Results, by contrast, pass small data like an image digest between Tasks without needing filesystem.', 'intermediate'),
('devops', 'tekton', 'overview', 'What three resources work together to make Tekton pipelines event-driven from a webhook?', '["Task, Pipeline, PipelineRun", "EventListener, TriggerBinding, TriggerTemplate", "Workspace, ClusterTask, Result", "GitRepository, Kustomization, HelmRelease"]', 1, 'EventListener receives the webhook, TriggerBinding extracts values (like the git URL and commit) from the payload, and TriggerTemplate creates a PipelineRun from those extracted values -- this is how Tekton wires to Git, similar in purpose to Jenkins webhooks or GitHub Actions triggers.', 'intermediate'),
('devops', 'tekton', 'overview', 'What is Tekton described as being deeply integrated with, as Red Hat''s distribution of the project?', '["Docker Swarm", "OpenShift Pipelines", "AWS CodePipeline", "Azure DevOps"]', 1, 'Tekton is deeply integrated with OpenShift Pipelines, Red Hat''s distribution of Tekton -- making it a natural fit for teams already standardized on OpenShift as their Kubernetes platform.', 'beginner'),

-- ---------- devops/tekton/fundamentals ----------
('devops', 'tekton', 'fundamentals', 'Per the core-concepts table, what actually creates the pods when a Pipeline is executed?', '["Applying the Pipeline YAML with kubectl apply", "Creating a PipelineRun -- one execution instance of a Pipeline, which orchestrates multiple pods sequentially", "The Task definition alone, before any run is created", "The Trigger resource, independent of any PipelineRun"]', 1, 'Per the core-concepts table, a PipelineRun is one execution instance of a Pipeline and is what actually runs as multiple pods sequentially -- a Pipeline alone is just a template that does nothing until a PipelineRun is created against it.', 'intermediate'),
('devops', 'tekton', 'fundamentals', 'Per the Tekton-vs-Jenkins-vs-GitHub-Actions comparison table, what credential model does Tekton use?', '["A separate Jenkins-style credential store", "Kubernetes Secrets -- the same credential model applications already use", "GitHub Secrets / Vars, shared with GitHub Actions", "A proprietary Tekton credential vault"]', 1, 'Per the comparison table, Tekton uses Kubernetes Secrets for credentials -- the same model as applications running in the cluster, unlike Jenkins''s separate credential store or GitHub''s own Secrets/Vars system.', 'intermediate'),
('devops', 'tekton', 'fundamentals', 'Without a Workspace, why can''t a build Task access the code a preceding git-clone Task fetched?', '["Tekton automatically shares files between all Tasks by default", "Each Task runs as a separate Pod, and without a shared Workspace (backed by a PersistentVolumeClaim), the build Task has no access to files the clone Task wrote in its own separate pod", "git-clone Tasks are not allowed to run before build Tasks", "Workspaces are only required for Pipelines with more than 5 Tasks"]', 1, 'Each Task runs as a separate Pod. Without a Workspace, the git-clone Task clones code but the build Task cannot access it, since separate pods don''t share a filesystem -- a Workspace, backed by a PVC, is what binds them together for the PipelineRun.', 'intermediate'),
('devops', 'tekton', 'fundamentals', 'In the Trigger example, what does the TriggerBinding resource specifically do with an incoming webhook payload?', '["It creates the PipelineRun directly", "It extracts specific data (like the git repo URL and revision) from the webhook payload, for the TriggerTemplate to then use", "It verifies the webhook signature for security", "It defines which Tasks the Pipeline will run"]', 1, 'TriggerBinding extracts data from the webhook payload (e.g. $(body.repository.clone_url) for the git URL) -- it is the TriggerTemplate that then uses those extracted values to actually create a PipelineRun.', 'intermediate'),
('devops', 'tekton', 'fundamentals', 'Per the core-concepts table, what is the smallest unit of execution in Tekton?', '["A Task", "A Step -- a single container command inside a Task", "A PipelineRun", "A Workspace"]', 1, 'Per the core-concepts table, a Step is a single container command and the smallest unit; a Task is an ordered sequence of Steps sharing a workspace, running as a single Kubernetes Pod.', 'beginner'),

-- ---------- devops/tekton/intermediate ----------
('devops', 'tekton', 'intermediate', 'What does a Pipeline''s finally: block guarantee that its regular tasks: list does not?', '["finally tasks run before any regular task starts", "finally tasks run after all regular tasks complete, regardless of whether the pipeline succeeded or failed -- like a try/finally block", "finally tasks can only be used for security scanning", "finally tasks skip execution if any regular task fails"]', 1, 'Tasks in a finally: block run after all regular tasks complete regardless of overall success or failure -- the direct equivalent of a try/finally block, useful for cleanup or notifications that must run either way.', 'intermediate'),
('devops', 'tekton', 'intermediate', 'Why is $(tasks.<name>.status) only accessible from within a finally: block?', '["It is a Tekton limitation with no real benefit", "It is what lets a single notification task correctly report success or failure, rather than needing separate success-path and failure-path notification tasks duplicated across the pipeline", "It is a security restriction preventing any task from checking another''s status", "Regular tasks never have a status field at all"]', 1, '$(tasks.<name>.status) being available specifically in finally: is what lets one notify-slack task correctly report "succeeded" or "failed" for the pipeline overall, instead of needing separate, duplicated success-path and failure-path notification tasks.', 'advanced'),
('devops', 'tekton', 'intermediate', 'What specific gap does Tekton Results close, relative to relying on the pods themselves for run history?', '["It replaces the need for a Workspace entirely", "Kubernetes garbage-collects completed pods (and their logs) after a retention period; Tekton Results retains PipelineRun/TaskRun history and logs beyond that window in a separate API and database", "It prevents PipelineRuns from ever completing", "It only stores metrics, not logs"]', 1, 'Kubernetes garbage-collects completed pods and their logs after a retention window -- Tekton Results is the purpose-built solution for retaining PipelineRun/TaskRun history and logs beyond that, storing them separately rather than relying on the originating pods persisting.', 'advanced'),
('devops', 'tekton', 'intermediate', 'Setting timeouts.tasks and timeouts.finally separately from timeouts.pipeline matters most for which specific scenario?', '["Pipelines with only one Task", "Pipelines with cleanup logic in finally: -- a single flat timeout risks firing mid-cleanup, leaving resources in a half-cleaned state", "Pipelines that never use Workspaces", "Pipelines triggered manually rather than via webhook"]', 1, 'Setting tasks and finally timeouts separately from the overall pipeline timeout matters specifically for pipelines with cleanup logic in finally: -- a single flat timeout risks the timeout firing mid-cleanup, leaving resources in a half-cleaned state.', 'advanced'),
('devops', 'tekton', 'intermediate', 'What does adding a sidecar to a Task definition provide, and when is it automatically torn down?', '["A sidecar provides a second copy of the main step; it never stops", "A companion process (e.g. a database) running alongside the step for its duration, reachable at localhost -- it is automatically torn down when the Task completes", "Sidecars run before the Task starts and stop before the first step begins", "Sidecars require a separate Pipeline to manage their lifecycle"]', 1, 'A Task sidecar (e.g. a postgres container) starts before the step begins and is reachable at localhost for the duration of that step -- it is automatically torn down when the Task completes, providing test dependencies without a separately-managed external database.', 'intermediate'),

-- ---------- devops/tekton/advanced ----------
('devops', 'tekton', 'advanced', 'What does Tekton Chains actually generate for a completed TaskRun that produces an OCI image?', '["A performance benchmark report", "A signed provenance attestation cryptographically linking the built artifact back to the exact pipeline execution, source commit, and Task versions that produced it", "An automatic rollback plan", "A cost estimate for the build"]', 1, 'Tekton Chains observes completed TaskRuns and automatically generates and signs provenance attestations, cryptographically linking a built artifact back to the exact pipeline execution that produced it -- the basis for SLSA compliance.', 'advanced'),
('devops', 'tekton', 'advanced', 'In a multi-tenant Tekton cluster, what determines whether Team A''s pipeline can reach resources it shouldn''t?', '["Kubernetes automatically isolates all pods regardless of configuration", "The RBAC actually attached to the ServiceAccount each PipelineRun uses -- without deliberate scoping, an over-privileged default ServiceAccount lets any team''s pipeline reach far more than it should", "The number of Tasks in the Pipeline", "Whether the Pipeline uses a Workspace"]', 1, 'Every Task runs as a pod with whatever ServiceAccount its PipelineRun specifies -- isolation is only as real as the RBAC actually attached to that ServiceAccount, not something Tekton enforces automatically by default (the same principle as FluxCD''s per-tenant ServiceAccount scoping).', 'advanced'),
('devops', 'tekton', 'advanced', 'What does disabling the Affinity Assistant specifically unlock, and under what condition is it safe to do?', '["It unlocks faster pod scheduling always, with no tradeoffs", "It removes the same-node scheduling constraint for Tasks sharing a Workspace, safe specifically when using a storage class supporting ReadWriteMany rather than ReadWriteOnce", "It disables Workspaces entirely for the Pipeline", "It is required before any Pipeline can use a matrix strategy"]', 1, 'The Affinity Assistant controls whether Tasks sharing a Workspace get scheduled onto the same node, required for ReadWriteOnce volumes. Disabling it removes that same-node constraint, but is described as safe specifically with a storage class supporting ReadWriteMany.', 'advanced'),
('devops', 'tekton', 'advanced', 'What does the Tekton Operator manage, using the same pattern as the Prometheus Operator?', '["Individual TaskRun logs", "The full component lifecycle (install, upgrade, configuration) of Tekton Pipelines, Triggers, Chains, and Dashboard together, as a single declarative custom resource", "Only the Tekton Dashboard UI specifically", "Kubernetes node scaling"]', 1, 'The Tekton Operator manages the full component lifecycle (install, upgrade, configuration) as a single TektonConfig custom resource -- the same pattern the Prometheus Operator uses for managing Prometheus/Alertmanager instances, making "every cluster runs the same Tekton version" a declarative fact.', 'advanced'),
('devops', 'tekton', 'advanced', 'A matrix strategy on a Tekton Pipeline task with three node-version values generates how many TaskRuns from one Task reference?', '["One TaskRun that tests all three versions sequentially", "Three parallel TaskRuns, one per parameter value", "Nine TaskRuns, since matrix always multiplies by 3", "Zero TaskRuns until manually triggered per version"]', 1, 'Tekton''s matrix strategy generates one parallel TaskRun per parameter combination -- three node-version values produce three parallel TaskRuns from a single Task reference, the same conceptual feature as GitLab CI''s parallel: matrix.', 'intermediate'),

-- ---------- devops/ebpf/overview ----------
('devops', 'ebpf', 'overview', 'What does eBPF allow that traditionally required writing a kernel module?', '["Running sandboxed programs inside the Linux kernel without modifying kernel source or inserting modules", "Replacing the Linux kernel entirely with a custom kernel", "Running Windows applications on a Linux kernel", "Bypassing the need for containers entirely"]', 0, 'eBPF (extended Berkeley Packet Filter) allows running sandboxed programs inside the Linux kernel without modifying kernel source code or inserting kernel modules -- observing network connections, syscalls, and file access at the kernel level with zero application changes.', 'beginner'),
('devops', 'ebpf', 'overview', 'Per the stated performance comparison, why is Cilium''s eBPF-based approach faster than iptables-based kube-proxy at scale?', '["Cilium uses less memory than iptables regardless of scale", "iptables uses O(n) rule lookup, which slows down as service count grows; eBPF uses O(1) hash lookup, staying the same speed regardless of scale", "iptables is deprecated and no longer maintained", "Cilium bypasses the Linux kernel entirely"]', 1, 'iptables (kube-proxy) uses O(n) rule lookup -- slow with 10,000+ services. eBPF (Cilium) uses O(1) hash lookup -- same speed regardless of scale, resulting in roughly 2-3x better network throughput.', 'intermediate'),
('devops', 'ebpf', 'overview', 'What does CiliumNetworkPolicy add that a standard Kubernetes NetworkPolicy cannot express?', '["Blocking traffic based on source IP address", "L7/HTTP-aware rules, e.g. allowing only POST requests to a specific path, not just L3/L4 IP-and-port rules", "Restricting which namespace a pod can be created in", "Setting resource limits on a pod"]', 1, 'CiliumNetworkPolicy is L7-aware -- in the example, it allows POST specifically to /api/payment from orders-service, something standard K8s NetworkPolicy (L3/L4 only) fundamentally cannot express since it only understands IPs and ports.', 'advanced'),
('devops', 'ebpf', 'overview', 'What does Hubble specifically provide that distinguishes it from Cilium''s core networking function?', '["Hubble replaces Cilium as the CNI itself", "Real-time network flow visibility -- seeing which pods talk to which, with what HTTP paths", "Hubble manages Helm chart installations", "Hubble is only used for CPU profiling"]', 1, 'Hubble provides real-time network flow visibility -- which pods talk to which, with what HTTP paths -- as Cilium''s own observability layer, distinct from Cilium''s core function of enforcing network policy and replacing kube-proxy.', 'beginner'),
('devops', 'ebpf', 'overview', 'Per the tools summary, what does Tetragon add beyond what Falco does at the syscall level?', '["Tetragon only observes, it cannot take action", "Tetragon is positioned as runtime security that can detect AND block/kill processes, going beyond alert-only detection", "Tetragon replaces Hubble for network observability", "Tetragon only works on non-Kubernetes hosts"]', 1, 'Tetragon can detect a cryptominer the moment it makes a suspicious syscall and block it before any damage -- an enforcement capability described alongside Falco and Pixie in the tools summary, going beyond pure detection/alerting.', 'intermediate'),

-- ---------- devops/ebpf/fundamentals ----------
('devops', 'ebpf', 'fundamentals', 'Per the hook-points table, which hook point observes packets before they reach the kernel''s networking stack, making it suited for DDoS mitigation?', '["kprobe/tracepoint", "TC (Traffic Control)", "XDP (Express Data Path)", "Uprobe"]', 2, 'XDP (Express Data Path) observes packets before the kernel networking stack -- used for ultra-fast packet filtering and DDoS mitigation, since it can drop unwanted traffic before the kernel has even processed it.', 'advanced'),
('devops', 'ebpf', 'fundamentals', 'Per the hook-points table, what does a Uprobe attach to, and what does that enable?', '["Kernel system calls only", "User-space function calls (like libc or application code), enabling zero-instrumentation tracing of an application", "Network packets at ingress only", "Only the Linux kernel scheduler"]', 1, 'Uprobes attach to user-space function calls (libc, application code) -- enabling zero-instrumentation app tracing, which is the mechanism behind tools like Pixie observing application behavior without code changes.', 'advanced'),
('devops', 'ebpf', 'fundamentals', 'Before eBPF, what did observing or changing kernel behavior typically require?', '["A simple configuration file change", "Writing kernel modules -- complex C code that could crash the system, required kernel recompiles, and needed server reboots to load", "Nothing; it was already possible without any special tooling", "A commercial license from a kernel vendor"]', 1, 'Before eBPF, observing or changing kernel behavior required writing kernel modules -- complex C code that could crash the system, required kernel recompiles, and needed reboots. eBPF programs load at runtime in milliseconds with no reboot.', 'beginner'),
('devops', 'ebpf', 'fundamentals', 'Per the "what makes eBPF important for Kubernetes" table, what is the tradeoff of userspace-agent-based runtime security monitoring, compared to eBPF kernel probes?', '["Userspace agents are always more accurate than eBPF probes", "Userspace agent polling has high overhead and can miss events, while eBPF kernel probes are near-instant with near-zero overhead", "Userspace agents require no installation at all", "eBPF kernel probes cannot detect security events, only performance issues"]', 1, 'Per the comparison table, userspace agent polling for runtime security monitoring has high overhead and misses events; eBPF kernel probes are instant with near-zero overhead, since they observe directly at the kernel level rather than polling from outside.', 'intermediate'),
('devops', 'ebpf', 'fundamentals', 'Per the Cilium feature table, what does Transparent Encryption provide without requiring a sidecar?', '["Automatic code signing for container images", "WireGuard or IPSec encryption between nodes", "Automatic database backups", "DNS-level ad blocking"]', 1, 'Transparent Encryption provides WireGuard or IPSec encryption between nodes with no sidecar needed -- encrypting pod-to-pod traffic across nodes at the eBPF datapath level directly.', 'intermediate'),

-- ---------- devops/ebpf/intermediate ----------
('devops', 'ebpf', 'intermediate', 'What is the key functional difference between Falco and Tetragon, given both operate at the kernel level?', '["They are functionally identical tools with different names", "Falco alerts on suspicious kernel-level behavior; Tetragon can actively enforce policy, killing a process or blocking a syscall the moment it violates policy, not just logging it", "Falco can only run outside of Kubernetes", "Tetragon only works with Docker, not containerd"]', 1, 'Falco alerts on suspicious kernel-level behavior after the fact; Tetragon goes further and can actively enforce policy in-kernel -- killing a process or blocking a syscall the moment it violates policy, before the malicious action''s effects propagate.', 'intermediate'),
('devops', 'ebpf', 'intermediate', 'What is bpftrace best described as, relative to Cilium/Hubble/Tetragon?', '["A continuously-running production monitoring system, just like Cilium", "A debugging/investigation tool for ad hoc, interactive one-liners answering a specific question, not a continuously deployed production system", "A replacement for Kubernetes NetworkPolicy", "A GUI-only tool with no command-line interface"]', 1, 'bpftrace is explicitly a debugging/investigation tool -- its one-liners are written and run interactively for a specific question, in contrast to Cilium/Hubble/Tetragon, which run continuously as a deployed part of the cluster.', 'intermediate'),
('devops', 'ebpf', 'intermediate', 'Why is XDP capable of genuinely line-rate packet filtering in a way that standard TC-hooked eBPF is not?', '["XDP runs on a completely separate physical network card", "XDP hooks at the network driver level, before the kernel network stack processes the packet at all, skipping that processing entirely for packets it drops or redirects", "XDP uses a faster programming language than TC-hooked eBPF", "TC-hooked eBPF cannot run in Kubernetes clusters at all"]', 1, 'XDP hooks even earlier than TC -- at the network driver level, before the kernel stack processes the packet at all. This is what makes it capable of line-rate filtering: it skips kernel network-stack processing entirely for packets it decides to drop.', 'advanced'),
('devops', 'ebpf', 'intermediate', 'What gap does Pixie fill that Hubble does not, even though both use eBPF for observability?', '["Pixie only works for network-layer traffic, same as Hubble", "Pixie shows the actual application-level content of traffic (HTTP path, response code, SQL query text) using uprobes, while Hubble shows that traffic flowed and whether it was allowed", "Pixie requires application code changes while Hubble does not", "Hubble only works with TCP, Pixie only works with UDP"]', 1, 'Hubble shows that traffic flowed between two pods and whether it was allowed; Pixie uses eBPF uprobes to show the actual application-level content (HTTP path, response code, SQL query text) with zero code changes -- a different layer of visibility.', 'advanced'),
('devops', 'ebpf', 'intermediate', 'In the TracingPolicy example, what does setting matchActions with action: Sigkill actually cause Tetragon to do?', '["Log the event only, take no further action", "Actively terminate the offending process in-kernel the moment the policy match fires, before the malicious action''s effects can propagate", "Send an email notification to the security team", "Restart the entire node the process was running on"]', 1, 'action: Sigkill causes Tetragon to actively terminate the process in-kernel the moment it violates the policy -- this in-kernel enforcement happens before the malicious action''s effects propagate, faster than a userspace tool that observes a log line and then reacts.', 'advanced'),

-- ---------- devops/ebpf/advanced ----------
('devops', 'ebpf', 'advanced', 'What specifically does the eBPF verifier reject an unbounded while(true) loop for?', '["Unbounded loops are actually allowed if marked with a special flag", "The verifier cannot prove the loop terminates, and every eBPF program must be provably bounded before being allowed to load", "while(true) loops are a syntax error in eBPF C, unrelated to the verifier", "The verifier only rejects loops that access memory"]', 1, 'The verifier statically analyzes every possible execution path before allowing a program to load, rejecting anything it can''t prove terminates -- an unbounded while(true) is rejected outright because the verifier cannot prove it ever stops.', 'advanced'),
('devops', 'ebpf', 'advanced', 'What problem does CO-RE (Compile Once, Run Everywhere) solve for eBPF programs deployed across a fleet?', '["It makes eBPF programs run faster on every kernel version", "Early eBPF programs had to be compiled separately per kernel version since data structure layouts differ across versions; CO-RE lets one compiled program adapt at load time using BTF metadata", "It removes the need for the kernel verifier entirely", "It only applies to XDP programs, not TC-hooked ones"]', 1, 'CO-RE solves the real deployment problem of needing a separately-compiled binary per kernel version -- using BTF (BPF Type Format) metadata embedded in the kernel, a single CO-RE-compiled program adapts its memory-layout assumptions at load time to whatever kernel it actually runs on.', 'advanced'),
('devops', 'ebpf', 'advanced', 'Between WireGuard and IPSec for Cilium''s transparent encryption, which is described as generally the simpler operational choice, and when would the alternative be chosen instead?', '["IPSec is simpler; WireGuard only used for specific compliance mandates", "WireGuard is generally simpler (lower CPU overhead, simpler key rotation) unless a specific compliance framework mandates IPSec by name", "Both are functionally and operationally identical with no tradeoffs", "Neither can be used together with Cilium; a third tool is required"]', 1, 'WireGuard is generally the simpler operational choice -- simpler key rotation, lower CPU overhead -- unless a specific compliance requirement mandates IPSec specifically; this is presented as a case where the "better" choice is genuinely conditional on an external requirement.', 'advanced'),
('devops', 'ebpf', 'advanced', 'What real production problem does Cilium''s Egress Gateway solve?', '["It load-balances incoming traffic across multiple ingress points", "An external partner system needs cluster traffic to originate from a small, predictable set of IPs, not the potentially-changing pod IPs a dynamic cluster naturally produces", "It encrypts all traffic leaving the cluster automatically", "It prevents pods from making any outbound connections at all"]', 1, 'Egress Gateway routes egress traffic matching a policy through designated gateway nodes, presenting a consistent, predictable source IP externally -- solving the real requirement of a partner API or legacy firewall needing traffic from a small, stable IP set rather than changing pod IPs.', 'advanced'),
('devops', 'ebpf', 'advanced', 'Presence of /sys/kernel/btf/vmlinux on a host indicates what, in the context of CO-RE?', '["The host has no eBPF support at all", "The kernel exposes its own type information, which CO-RE-compiled programs read at load time to correctly resolve struct offsets for that specific kernel", "The host is running a security-hardened kernel with eBPF disabled", "The file only matters for XDP programs, not other eBPF programs"]', 1, 'The presence of /sys/kernel/btf/vmlinux confirms the kernel exposes BTF (its own type information), which CO-RE-compiled programs read at load time to resolve struct offsets correctly for that specific kernel -- required for CO-RE to function at all.', 'advanced'),

-- ---------- devops/harbor/overview ----------
('devops', 'harbor', 'overview', 'What is Docker Hub explicitly called out as a poor choice for in production, per the registry comparison?', '["It cannot store container images at all", "Rate limiting (100 pulls per 6 hours unauthenticated) and outages affecting all downstream builds", "It does not support Docker at all, only Kubernetes manifests", "It requires a paid account for any usage whatsoever"]', 1, 'Docker Hub is called out to avoid for production specifically due to rate limiting (100 pulls/6 hours unauthenticated) and because outages affect all downstream builds -- a real availability and throughput risk for production CI/CD.', 'beginner'),
('devops', 'harbor', 'overview', 'What does a Harbor Project provide, structurally?', '["A single global RBAC policy shared across the entire registry", "A namespace-like isolation unit, each with its own RBAC, scanning policy, and retention rules", "A separate physical server for each project", "A billing account, unrelated to access control"]', 1, 'Harbor organizes images into Projects, functioning like namespaces -- each project has its own RBAC, scanning policy, and retention rules, letting different teams have different access and policies within one Harbor instance.', 'beginner'),
('devops', 'harbor', 'overview', 'What does configuring Harbor''s prevent_vul policy with severity critical actually enforce?', '["It only generates a report; nothing is actually blocked", "It blocks pushes and pulls of images with CRITICAL-severity vulnerabilities, as detected by Harbor''s built-in Trivy scanning", "It deletes any image older than 30 days automatically", "It requires two-factor authentication for all pushes"]', 1, 'Trivy is built into Harbor for scanning -- configuring prevent_vul with severity critical actually blocks pushes and pulls of images carrying CRITICAL CVEs, turning scanning into an enforced gate rather than passive reporting.', 'intermediate'),
('devops', 'harbor', 'overview', 'Per the guide''s own framing, what distinguishes Nexus/Artifactory from Harbor specifically?', '["Nexus/Artifactory cannot store Docker images at all", "Nexus and Artifactory are universal artifact managers handling Maven JARs, npm packages, PyPI, and more, not just Docker images the way Harbor is primarily focused", "Harbor is a paid-only product while Nexus/Artifactory are always free", "Nexus/Artifactory do not support any form of RBAC"]', 1, 'Nexus and Artifactory are universal artifact managers -- handling not just Docker images but also Maven JARs, npm packages, Python PyPI, Helm charts, and more, distinct from Harbor''s container-image-focused design.', 'intermediate'),
('devops', 'harbor', 'overview', 'What does Harbor''s replication feature specifically sync, and for what stated purpose?', '["It syncs user accounts between two Harbor instances", "It syncs images to other registries (ACR, ECR, another Harbor) for multi-cloud availability or disaster recovery", "It syncs Kubernetes manifests to a Git repository", "It syncs vulnerability scan configurations only, not images"]', 1, 'Replication syncs images to other registries (ACR, ECR, another Harbor) for multi-cloud or DR -- ensuring images remain available even if the primary registry instance is down, or across cloud providers.', 'intermediate'),

-- ---------- devops/harbor/fundamentals ----------
('devops', 'harbor', 'fundamentals', 'In the air-gapped telco scenario, what specifically enables production pods in the isolated network to get scanned, current images?', '["Production pods pull directly from the internet-facing Harbor", "A replication rule syncs production-tagged images from the internet-facing Harbor to the air-gapped Harbor inside the customer network on a schedule (every 4 hours)", "Images are manually copied via USB drive on a monthly basis", "The air-gapped Harbor generates its own images without any external source"]', 1, 'A replication rule syncs production-tagged images to the air-gapped Harbor inside the customer network every 4 hours -- production pods then pull from the local registry with zero internet dependency, while still getting vulnerability scanning in both environments.', 'intermediate'),
('devops', 'harbor', 'fundamentals', 'Per the architecture table, what role does Harbor''s Core component specifically play?', '["It stores the actual image layers and manifests", "It is the API server handling all Harbor API calls, authentication, and RBAC", "It is the web UI for project management", "It is the vulnerability scanner"]', 1, 'Per the architecture table, Core is the API server -- it handles all Harbor API calls, authentication, and RBAC, distinct from Registry (which stores the actual image layers) and Portal (the web UI).', 'intermediate'),
('devops', 'harbor', 'fundamentals', 'Why does an attacker with the ability to push a same-tagged malicious image matter, and what specifically defends against it?', '["It doesn''t matter; Kubernetes always verifies image content automatically", "Without signing, Kubernetes can''t tell a legitimate CI-built image from a same-tagged malicious one; Cosign signing plus a Kyverno policy rejects any unsigned image at the cluster level", "RBAC alone fully prevents this without needing signing", "Only Notary, never Cosign, can address this risk"]', 1, 'Without image signing, Kubernetes cannot distinguish an image actually built by CI/CD from a malicious image pushed with the same tag. Cosign signing combined with a Kyverno policy rejecting unsigned images closes this gap at the cluster admission level.', 'advanced'),
('devops', 'harbor', 'fundamentals', 'Per the scan-trigger table, what specifically does a Scheduled scan catch that Scan on push does not?', '["Scheduled scans catch nothing that scan-on-push doesn''t already catch", "Newly-discovered CVEs in old images that were already pushed before that CVE was known -- scan on push only catches issues known at the time of the original push", "Scheduled scans only check image size, not vulnerabilities", "Scan on push is deprecated in favor of scheduled scans only"]', 1, 'Per the scan-trigger table, Scheduled scan re-scans all images on a schedule specifically to catch newly-discovered CVEs in old, already-pushed images -- a vulnerability disclosed after an image was pushed would be missed by scan-on-push alone, which only knew about CVEs current at push time.', 'advanced'),
('devops', 'harbor', 'fundamentals', 'What are the two replication modes Harbor supports for syncing images between registries?', '["Manual-only and API-only", "Push-based (Harbor pushes to the target on push) and pull-based (Harbor pulls from the source on a schedule)", "Encrypted and unencrypted, with no scheduling difference", "Full-registry only; per-project replication is not supported"]', 1, 'Harbor replication can be push-based (Harbor pushes to the target when an image is pushed) or pull-based (Harbor pulls from the source on a schedule) -- common uses include dev-to-production sync and disaster-recovery copies in a second region.', 'intermediate'),

-- ---------- devops/harbor/intermediate ----------
('devops', 'harbor', 'intermediate', 'Why are Harbor robot accounts preferred over using a real user''s credentials for CI/CD pipeline pushes?', '["Robot accounts are faster at pushing images than user credentials", "Real user credentials tie automation to an individual (breaking when they leave or rotate a password) and typically grant broader access than a pipeline needs; robot accounts are scoped, non-human, per-project credentials", "Robot accounts never expire, unlike user credentials", "Robot accounts are required for Harbor to function at all, even for manual pushes"]', 1, 'Using a real user''s credentials for CI/CD is a common anti-pattern -- it ties automation to an individual and typically grants broader access than needed. Robot accounts are purpose-built, scoped, non-human credentials created per-project with explicit, minimal permissions.', 'intermediate'),
('devops', 'harbor', 'intermediate', 'What does setting an explicit duration on a Harbor robot account force?', '["It forces the account to have unlimited permissions", "A deliberate rotation cadence, rather than a credential that silently lives forever once created", "It disables the account immediately after first use", "It grants the account admin-level access automatically"]', 1, 'duration sets an expiry (in days) for a robot account -- it is not meant to be a permanent credential by default, and an explicit expiry forces deliberate rotation rather than a credential that silently persists indefinitely.', 'intermediate'),
('devops', 'harbor', 'intermediate', 'What does a Harbor webhook on SCANNING_COMPLETED specifically enable a CI pipeline to do?', '["It has no practical effect on pipeline behavior", "React to the scan result event-driven -- waiting on the webhook rather than polling the scan-status API in a loop, which is faster and lighter on the Harbor API", "It automatically retries a failed scan indefinitely", "It disables scanning for that specific push"]', 1, 'A common real pattern: a CI pipeline pushes an image and waits on the SCANNING_COMPLETED webhook rather than polling the scan-status API in a loop -- event-driven rather than poll-based, both faster and lighter on the Harbor API.', 'intermediate'),
('devops', 'harbor', 'intermediate', 'Why does tag immutability matter specifically for a release tag like v1.2.3, but matter less for a tag like latest or dev?', '["Immutability rules apply identically to all tags with no distinction possible", "A latest/dev tag being overwritten repeatedly is expected; a v1.2.3 tag being overwritten breaks the assumption that redeploying it later (e.g. for a rollback) gets the same content that was originally tested and released", "latest and dev tags cannot be scanned for vulnerabilities", "Tag immutability only applies to images larger than 1GB"]', 1, 'A latest or dev tag being overwritten repeatedly is expected and fine; a v1.2.3 release tag being overwritten is a genuine integrity problem, since a rollback that redeploys v1.2.3 later would silently get different content than what was originally tested.', 'advanced'),
('devops', 'harbor', 'intermediate', 'What does a project storage quota specifically contain, compared to the cluster-wide storage-full failure mode?', '["It has the same effect as a cluster-wide storage failure -- both block every team equally", "It turns a registry-wide ran-out-of-space failure caused by one team into that one team''s pushes failing at their own quota, containing the failure to the responsible project", "It only limits the number of projects that can be created, not storage", "Quotas are enforced only during scheduled maintenance windows"]', 1, 'In a multi-tenant Harbor instance, a quota caps storage/artifact count per project -- turning "the whole registry ran out of space because one team pushed excessively" into "that one team''s pushes started failing at their own quota," containing the failure rather than affecting every team sharing the instance.', 'advanced'),

-- ---------- devops/harbor/advanced ----------
('devops', 'harbor', 'advanced', 'Why does a real HA Harbor deployment need externally-managed PostgreSQL and Redis, rather than Harbor''s own bundled versions?', '["Harbor''s bundled PostgreSQL and Redis are always faster than external ones", "Harbor''s bundled PostgreSQL/Redis are fine for evaluation but aren''t themselves highly available -- scaling only the Harbor application components leaves the database layer as the single point of failure", "External databases are required by Harbor''s license terms", "Bundled PostgreSQL cannot store vulnerability scan results"]', 1, 'Harbor''s bundled PostgreSQL and Redis are fine for evaluation or single-instance use but aren''t themselves HA -- a genuine HA deployment needs those backing stores independently HA (managed PostgreSQL cluster, Redis Sentinel/Cluster), or scaling Harbor''s app components alone just moves the single point of failure to the database layer.', 'advanced'),
('devops', 'harbor', 'advanced', 'What does group-based RBAC mapping via OIDC specifically automate for Harbor access management?', '["It automatically scans every image for vulnerabilities", "Onboarding/offboarding a user from Harbor access as part of the org''s existing identity lifecycle process, since project-level permissions are driven by IdP group membership", "It replaces the need for Harbor Projects entirely", "It only works for LDAP, not OIDC-based identity providers"]', 1, 'Group-based RBAC mapping via the groups OIDC scope means a user''s project-level Harbor permissions are driven directly by their IdP group membership -- onboarding/offboarding happens automatically as part of the org''s existing identity process, not a separate manual Harbor step.', 'advanced'),
('devops', 'harbor', 'advanced', 'What does Harbor''s Dragonfly-based preheat feature solve for a large-scale cluster rollout?', '["It pre-scans images for vulnerabilities before they are pushed", "Registry bandwidth saturation when hundreds of nodes pull the same new image simultaneously -- preheat pre-distributes the image via peer-to-peer transfer instead of every node pulling independently", "It automatically retries failed pushes", "It compresses images before storage to save disk space"]', 1, 'Preheat, via Dragonfly P2P integration, pre-distributes an image across nodes using peer-to-peer transfer rather than every node independently pulling from the central registry -- keeping registry load roughly flat regardless of node count, instead of scaling linearly.', 'advanced'),
('devops', 'harbor', 'advanced', 'Why is a DR plan that backs up only Harbor''s PostgreSQL database considered a real, common gap?', '["PostgreSQL backup alone is always sufficient for any registry", "Harbor''s DR story has two separate concerns -- database metadata and actual image layer content -- and if the primary registry storage is lost, there may be no other copy of images only ever pushed to that one instance", "Harbor does not use PostgreSQL for anything important", "Image content is automatically backed up whenever the database is backed up"]', 1, 'Harbor''s DR story has two genuinely separate concerns: the database (metadata) and the image content (layer data). A DR plan backing up only the database and assuming image content is "just re-pullable from somewhere" is a real, common gap if the primary registry storage is actually lost.', 'advanced'),
('devops', 'harbor', 'advanced', 'What does provisioning Harbor projects via a Terraform provider specifically enable, compared to manual UI configuration?', '["It makes project creation instantaneous with zero configuration needed", "A new project''s RBAC, quota, and scan policy become reviewable in a pull request before being applied, rather than configured once by hand and left undocumented", "Terraform-provisioned projects cannot have vulnerability scanning enabled", "It removes the need for LDAP group mapping"]', 1, 'Using Harbor''s Terraform provider (or direct API calls) makes project provisioning declarative and repeatable -- a new project''s RBAC, quota, and scan policy are all reviewable in a pull request before being applied, rather than a one-time manual UI configuration that goes undocumented.', 'advanced'),

-- ---------- devops/keda/overview ----------
('devops', 'keda', 'overview', 'Why does a Kafka consumer pod with low CPU usage fail to trigger scaling under standard HPA, even when millions of messages are backed up?', '["HPA does not support scaling Kafka consumers under any configuration", "HPA only scales on CPU and memory, and a Kafka consumer can have low CPU even while badly behind on message backlog, since consuming a backlog isn''t necessarily CPU-intensive", "Kafka consumers are always CPU-bound, so this scenario cannot actually happen", "HPA requires manual approval before scaling any workload"]', 1, 'HPA only scales on CPU and memory -- a Kafka consumer pod can show low CPU even when 1 million messages are backed up, because consumer lag isn''t necessarily a CPU-intensive condition. HPA sees "everything is fine" and never scales it.', 'beginner'),
('devops', 'keda', 'overview', 'What is the KEDA CRD that replaces a raw HPA definition, and what does it reference?', '["Deployment, which replaces the need for HPA entirely", "ScaledObject -- it has a scaleTargetRef (the Deployment to scale), min/max replica counts, and triggers", "ConfigMap, which stores scaling thresholds as plain key-value pairs", "Ingress, which routes traffic based on load"]', 1, 'ScaledObject is the KEDA CRD that replaces HPA. It has a scaleTargetRef pointing at the target Deployment, min/max replica counts, and triggers defining what signal drives scaling decisions.', 'beginner'),
('devops', 'keda', 'overview', 'What is KEDA''s "killer feature" relative to standard HPA, per the stated framing?', '["Faster scaling response time under all conditions", "Scale to zero when there is no work, then scale up when messages arrive -- something standard HPA cannot do at all", "Support for Windows-based container workloads", "Automatic cost reporting per namespace"]', 1, 'KEDA''s killer feature is scaling to zero when the queue is empty, then scaling up when messages arrive -- standard HPA has a hard minimum of one replica and can never scale a workload down to genuinely zero.', 'beginner'),
('devops', 'keda', 'overview', 'What does activationLagThreshold specifically control, distinct from lagThreshold?', '["It sets the maximum number of replicas allowed", "It is the minimum lag required before scaling from zero to one replica, preventing thrashing on minor lag noise -- lagThreshold governs scaling beyond one replica once already active", "It controls how often KEDA polls the trigger source", "It has the same effect as lagThreshold; they are interchangeable"]', 1, 'activationLagThreshold is the minimum before scaling from zero specifically -- it prevents thrashing (rapid 0-to-1-to-0 oscillation on minor lag noise), while lagThreshold governs how much additional scaling happens once a replica is already active.', 'intermediate'),
('devops', 'keda', 'overview', 'What does a ScaledJob create per message, as opposed to how a ScaledObject scales a Deployment?', '["A ScaledJob and a ScaledObject behave identically", "A ScaledJob creates fresh Jobs per message, for one-off batch processing, rather than scaling a long-running Deployment''s replica count", "A ScaledJob only works with cron triggers, never queue-based triggers", "A ScaledJob requires manual approval before creating each Job"]', 1, 'KEDA ScaledJob is for one-off batch processing -- instead of scaling a Deployment''s replica count, it creates fresh Jobs per message (e.g. queueLength: "1" meaning one Job per message), suited to workloads that are naturally discrete units of work rather than a long-running service.', 'intermediate'),

-- ---------- devops/keda/fundamentals ----------
('devops', 'keda', 'fundamentals', 'Under the hood, what does KEDA actually create and manage when a ScaledObject is applied?', '["KEDA bypasses Kubernetes'' scaling mechanism entirely with its own custom scheduler", "KEDA creates and manages a standard Kubernetes HPA -- visible directly via kubectl get hpa", "KEDA only works in dry-run mode until manually activated", "KEDA replaces the target Deployment with a StatefulSet"]', 1, 'Under the hood, KEDA actually creates and manages a standard Kubernetes HPA -- kubectl get hpa shows it directly. KEDA''s real contribution is the scaler layer, translating an external signal into the metric the HPA scales against.', 'intermediate'),
('devops', 'keda', 'fundamentals', 'Why can''t standard HPA scale a workload down to genuinely zero replicas, unlike KEDA?', '["HPA has no minimum replica concept at all", "Standard HPA has a hard minimum of 1 replica, and can never scale below that even during guaranteed-zero-load periods", "HPA can scale to zero, but only for StatefulSets, not Deployments", "Scaling to zero is disabled by default in all Kubernetes clusters"]', 1, 'Standard HPA has a hard minimum of 1 replica -- it can never scale a workload down to zero, even during periods of guaranteed zero load. KEDA can, for genuinely idle event-driven workloads.', 'intermediate'),
('devops', 'keda', 'fundamentals', 'When multiple triggers (e.g. Kafka lag and CPU) are set on one ScaledObject, how do they combine by default?', '["AND logic -- all triggers must indicate scaling is needed", "OR logic -- the workload scales up if either condition indicates it should, taking the maximum recommended replica count across triggers", "Only the first-listed trigger is ever evaluated", "Triggers must be manually toggled between active and inactive"]', 1, 'Multiple triggers on one ScaledObject combine with OR logic by default -- the workload scales up if either condition indicates it should, taking the maximum recommended replica count across all triggers, useful for a workload with more than one real reason to need capacity.', 'intermediate'),
('devops', 'keda', 'fundamentals', 'What real advantage does cron-based scaling provide over purely metric-driven autoscaling, for genuinely predictable traffic?', '["Cron-based scaling responds faster to sudden, unpredictable spikes", "Capacity is already in place before predictable demand arrives, avoiding the reaction lag of scaling up only after load has already increased", "Cron-based scaling eliminates the need for a ScaledObject entirely", "Cron triggers cannot be combined with other trigger types"]', 1, 'For workloads with genuinely predictable, time-based traffic (business-hours APIs, overnight batch jobs), scheduled scaling avoids the reaction lag of purely metric-driven autoscaling -- capacity is already in place before the predictable demand arrives.', 'intermediate'),
('devops', 'keda', 'fundamentals', 'Without an activation threshold, what specific failure mode can a low-volume, bursty workload experience?', '["The workload never scales up at all, regardless of load", "The workload could scale from 0 to 1 the instant a single message arrives, then immediately back to 0 once processed, repeating rapidly -- wasteful pod-churn overhead", "The workload permanently stays at maxReplicaCount", "KEDA crashes and requires a manual restart"]', 1, 'Without a defined activation threshold, a workload could scale from 0 to 1 the instant a single message arrives, then immediately back to 0 once processed, repeating rapidly -- real, wasteful pod-churn overhead that activationLagThreshold is specifically designed to smooth out.', 'advanced'),

-- ---------- devops/keda/intermediate ----------
('devops', 'keda', 'intermediate', 'What is the advantage of a ScaledObject referencing a TriggerAuthentication resource, rather than embedding connection credentials directly?', '["TriggerAuthentication is required syntax with no functional benefit", "It separates credentials from the ScaledObject spec, referencing a Kubernetes Secret or cloud-native identity mechanism instead of hardcoding anything in the ScaledObject itself", "It makes the ScaledObject scale faster", "TriggerAuthentication is only usable with the cron trigger type"]', 1, 'Real deployments separate credentials into a dedicated TriggerAuthentication resource, referencing a Kubernetes Secret (or a cloud-native identity mechanism like IRSA/Workload Identity) rather than embedding connection details inline in the ScaledObject.', 'intermediate'),
('devops', 'keda', 'intermediate', 'Why is it a deliberate, common pattern to set scaleUp with a short stabilization window but scaleDown with a longer one?', '["It is not deliberate; it is a default Kubernetes bug", "Scaling up fast minimizes the latency impact of a genuine spike, while scaling down cautiously avoids prematurely removing capacity right before load returns -- an asymmetric, sound default", "Scaling down always needs to be faster than scaling up for cost reasons", "The stabilization window has no actual effect on scaling behavior"]', 1, 'The asymmetry (immediate scaleUp, a 5-minute scaleDown stabilization window in the example) is deliberate and common -- scaling up fast minimizes latency impact from a genuine spike, while scaling down cautiously avoids prematurely removing capacity right before load returns.', 'advanced'),
('devops', 'keda', 'intermediate', 'What is the specific difference between idleReplicaCount and minReplicaCount?', '["They are two names for the exact same setting", "minReplicaCount is the floor maintained once active; idleReplicaCount (set below minReplicaCount, often 0) is specifically the replica count during genuinely idle periods", "idleReplicaCount only applies to ScaledJobs, never ScaledObjects", "minReplicaCount always overrides idleReplicaCount regardless of configuration"]', 1, 'minReplicaCount is the floor the HPA maintains once active -- the workload never goes below it while actively scaled. idleReplicaCount, when set below minReplicaCount (often 0), is specifically the replica count during genuinely idle periods, letting the workload scale all the way down.', 'advanced'),
('devops', 'keda', 'intermediate', 'Why does a synchronous HTTP service scaled to zero need the KEDA HTTP Add-on''s interceptor proxy specifically?', '["HTTP services cannot use KEDA under any circumstances", "An incoming HTTP request needs something running to receive it; a scaled-to-zero Deployment has no pod to route to, so the interceptor proxy queues/holds requests while triggering scale-up, then forwards once ready", "The interceptor proxy is only needed for gRPC, not HTTP", "It replaces the need for a Kubernetes Service entirely"]', 1, 'A synchronous HTTP service scaled to zero has a structural problem: an incoming request needs something running to receive it. The interceptor proxy holds/queues the request while triggering scale-up, then forwards once a pod is ready -- without it, the first request after idle would simply fail.', 'advanced'),
('devops', 'keda', 'intermediate', 'What does horizontalPodAutoscalerConfig.behavior specifically let you tune, that a bare ScaledObject trigger configuration does not?', '["It tunes which trigger type is used", "The scaling rate itself -- stabilization windows and step sizes for scale-up and scale-down, since KEDA drives scaling through a standard HPA with its own default rate limits", "It tunes the polling interval for external metric sources", "It replaces the need for minReplicaCount and maxReplicaCount"]', 1, 'advanced.horizontalPodAutoscalerConfig.behavior is the direct lever for tuning the HPA''s scaling rate (stabilization windows, step-size policies for scale up/down) -- since KEDA drives scaling through a standard HPA that has its own default rate limits otherwise.', 'advanced'),

-- ---------- devops/keda/advanced ----------
('devops', 'keda', 'advanced', 'What does KEDA actually register itself as, within the Kubernetes ecosystem, to supply metrics to the HPA controller?', '["A custom Kubernetes scheduler", "A Kubernetes External Metrics API provider (keda-operator-metrics-apiserver), queried by the standard, unmodified HPA controller like any other metrics source", "A replacement for the Kubernetes API server itself", "A CNI plugin"]', 1, 'KEDA registers itself as a Kubernetes External Metrics API provider -- the standard HPA controller (unmodified) queries this API the same way it would query any metrics source, with KEDA translating that into a poll against the actual trigger (Kafka lag, queue depth, etc.).', 'advanced'),
('devops', 'keda', 'advanced', 'What does KEDA''s External Scaler interface let a team do for a trigger source with no built-in KEDA scaler?', '["Nothing; unsupported trigger sources cannot be used with KEDA at all", "Implement a custom gRPC service following KEDA''s externalscaler.proto contract (IsActive, GetMetricSpec, GetMetrics), which then participates in the same scaling pipeline as built-in scalers", "Manually poll the external system and update replica counts via a cron job instead", "Request KEDA''s maintainers add official support before it can be used"]', 1, 'The External Scaler interface lets a custom gRPC service implement the three-method contract (IsActive, GetMetricSpec, GetMetrics) that KEDA''s own built-in scalers use internally -- the deliberate escape hatch for any bespoke system that will never have an official KEDA scaler.', 'advanced'),
('devops', 'keda', 'advanced', 'Does KEDA itself provide cross-cluster/multi-region scaling coordination?', '["Yes, KEDA has a built-in federation feature for this specifically", "No -- each cluster''s KEDA installation only sees local triggers and workloads; genuine multi-cluster coordination has to be built on top, typically by feeding each cluster''s ScaledObject an already-global metric (e.g. via Prometheus federation)", "Yes, but only for Kafka triggers, not other trigger types", "No, and multi-cluster scaling is not achievable with KEDA under any pattern"]', 1, 'KEDA itself has no built-in cross-cluster awareness -- each cluster''s installation only sees local triggers/workloads. A genuine multi-cluster strategy has to be built on top, typically by feeding each region''s ScaledObject a trigger source that already reflects the global/aggregate state.', 'advanced'),
('devops', 'keda', 'advanced', 'With operator.replicaCount: 2 and Kubernetes leader election, how many KEDA Operator replicas are actively reconciling at once?', '["Both replicas reconcile simultaneously for redundancy", "Only one replica (the leader) actively reconciles at a time, via a Lease object, while the second stands by to take over if the leader''s lease isn''t renewed", "Neither replica reconciles until a third replica is added", "Reconciliation alternates between replicas every 60 seconds regardless of health"]', 1, 'KEDA''s Operator uses Kubernetes'' standard leader-election mechanism via a Lease object -- with replicaCount: 2, only one replica actively reconciles at a time (the leader), while the second stands by to take over immediately if the leader''s lease isn''t renewed, avoiding conflicting scaling decisions.', 'advanced'),
('devops', 'keda', 'advanced', 'Why is checking CRD compatibility before a KEDA version upgrade specifically important, beyond a normal version bump?', '["KEDA CRDs never change between versions, so this is unnecessary", "KEDA''s CRDs have had API version changes across major releases, and a schema change can leave an old-format resource silently un-reconciled rather than erroring loudly, which looks identical to a misconfigured-trigger failure but has a different root cause", "CRD compatibility only matters for ScaledJobs, never ScaledObjects", "Upgrading KEDA automatically migrates every existing resource with zero risk"]', 1, 'KEDA''s CRDs have gone through API version changes across major releases -- a schema change doesn''t necessarily reject an old-format resource outright, it can instead leave it silently un-reconciled, looking identical to a misconfigured-trigger failure but with a completely different root cause (an incompatible resource format).', 'advanced'),

-- ---------- devops/platform-engineering/overview ----------
('devops', 'platform-engineering', 'overview', 'Per the stated distinction, what is SRE described as, relative to DevOps?', '["SRE and DevOps are unrelated, competing philosophies", "SRE is Google''s implementation of DevOps -- using software engineering to solve operations problems, defining SLOs, and managing error budgets", "SRE is a subset of Platform Engineering with no independent identity", "SRE only applies to companies with fewer than 50 engineers"]', 1, 'SRE is described as Google''s implementation of DevOps -- it uses software engineering to solve operations problems, defines SLOs, and manages error budgets, operationalizing DevOps culture with specific measurable practices.', 'beginner'),
('devops', 'platform-engineering', 'overview', 'What does Platform Engineering specifically build, per the stated distinction from DevOps and SRE?', '["A set of company-wide HR policies", "The internal platform developers use -- the golden path, the paved road for common tasks", "A replacement for the Kubernetes API server", "A dedicated hardware data center"]', 1, 'Platform Engineering builds the internal platform that developers use -- the golden path, the paved road -- distinct from DevOps (a culture) and SRE (Google''s operationalized implementation of that culture).', 'beginner'),
('devops', 'platform-engineering', 'overview', 'What is an Internal Developer Platform (IDP) described as giving application developers?', '["Direct root access to every production server", "A self-service portal to deploy applications, spin up databases, and create pipelines without knowing Kubernetes or Terraform internals", "A mandatory weekly training session on infrastructure", "Unlimited free cloud compute with no cost tracking"]', 1, 'An IDP gives application developers a self-service portal to deploy applications, spin up databases, and create pipelines -- without needing to know Kubernetes or Terraform internals directly, reducing the cognitive load on developers whose actual job is building features.', 'intermediate'),
('devops', 'platform-engineering', 'overview', 'Who is credited as the origin of Backstage, and what is its current governance status?', '["Google originally, now governed by the Linux Foundation", "Spotify originally, now a CNCF project", "Amazon originally, still fully proprietary", "Red Hat originally, now part of OpenShift only"]', 1, 'Backstage originated at Spotify and is now a CNCF project -- described as the most popular IDP portal, used by companies well beyond Spotify itself.', 'beginner'),
('devops', 'platform-engineering', 'overview', 'Per the stated interview-answer framing, how might one senior engineer plausibly touch all three of DevOps, SRE, and Platform Engineering in a single role?', '["The three are mutually exclusive; no one role can span all three", "By maintaining SLOs (SRE), building shared Terraform modules and CI templates (Platform), and working closely with developers to remove friction (DevOps), all as part of one job", "Only by holding three separate, simultaneous job titles at three different companies", "By automating all three away entirely using AI tooling"]', 1, 'The sample interview answer frames this concretely: maintaining SLOs is SRE work, building shared Terraform modules and CI templates is Platform work, and working closely with developers to remove friction is DevOps -- all three done by one person in one current role.', 'intermediate'),

-- ---------- devops/platform-engineering/fundamentals ----------
('devops', 'platform-engineering', 'fundamentals', 'Per the traditional-DevOps-vs-Platform-Engineering table, who owns infrastructure provisioning under Platform Engineering, compared to traditional DevOps?', '["Each individual developer owns their own infrastructure provisioning in both models equally", "The platform team owns the infrastructure and developers consume it via self-service, versus each team managing its own CI/CD, K8s config, and monitoring under traditional DevOps", "No one owns infrastructure provisioning under Platform Engineering; it is fully automated with no team responsible", "An external vendor owns all infrastructure under Platform Engineering"]', 1, 'Per the comparison table, under traditional DevOps each team manages its own CI/CD, K8s config, and monitoring; under Platform Engineering, the platform team owns the infrastructure and developers consume it via self-service instead.', 'beginner'),
('devops', 'platform-engineering', 'fundamentals', 'What problem is Platform Engineering described as solving that DevOps culture itself created?', '["DevOps culture eliminated the need for any infrastructure expertise", "DevOps culture made developers own their services end-to-end, but this requires every developer to be an expert in Kubernetes, Terraform, CI/CD, security, and compliance simultaneously -- too much cognitive load", "DevOps culture is described as having caused no new problems at all", "DevOps culture removed the need for any operations team permanently"]', 1, 'DevOps broke the wall between dev and ops so developers own their services end-to-end -- but this created the new problem of every developer needing deep expertise across Kubernetes, Terraform, CI/CD, and compliance simultaneously, which Platform Engineering solves by absorbing that complexity into a product.', 'intermediate'),
('devops', 'platform-engineering', 'fundamentals', 'What does the Crossplane PostgreSQLInstance example specifically abstract away from the requesting developer?', '["It abstracts away the need for a database entirely", "It hides the underlying Terraform-equivalent cloud resources (VPC subnet, security group, RDS instance) behind a simple, developer-facing manifest", "It requires the developer to write the full Terraform configuration manually first", "It only works for MySQL, not PostgreSQL"]', 1, 'A developer applies a simple PostgreSQLInstance manifest; Crossplane''s composition translates it into the full underlying Terraform-equivalent resources (VPC subnet, security group, RDS instance) behind the scenes -- the developer never touches the underlying complexity.', 'intermediate'),
('devops', 'platform-engineering', 'fundamentals', 'Per the DORA metrics table, what Change Failure Rate range is classified as "Elite"?', '["15%+", "10-15%", "5-10%", "0-5%"]', 3, 'Per the DORA metrics table, a Change Failure Rate of 0-5% is classified as Elite -- the lowest percentage of deployments causing incidents, contrasted with 15%+ classified as Low performance.', 'intermediate'),
('devops', 'platform-engineering', 'fundamentals', 'What are the four core Backstage capabilities described in the table?', '["Billing, Support, Legal, HR", "Software Catalog, Software Templates, TechDocs, Plugins", "Load Balancing, Auto-scaling, Monitoring, Alerting", "Authentication, Authorization, Encryption, Auditing"]', 1, 'Backstage''s four core capabilities per the table are Software Catalog (service registry), Software Templates (click-to-create scaffolding), TechDocs (documentation-as-code), and Plugins (integrations like Kubernetes, ArgoCD, PagerDuty).', 'beginner'),

-- ---------- devops/platform-engineering/intermediate ----------
('devops', 'platform-engineering', 'intermediate', 'What is the core mindset shift described as separating a platform team that achieves genuine adoption from one that ships tooling nobody uses?', '["Hiring more platform engineers regardless of team structure", "Treating the internal platform itself as a product with the org''s own engineers as its customers, rather than an internal IT project shipped once and considered done", "Only building tools that require no documentation", "Mandating adoption via executive policy rather than earning it"]', 1, 'The single mindset shift is treating the internal platform as a product, with the org''s own engineers as its customers -- not an internal IT project that ships once and is done. This has concrete consequences: a product roadmap, documentation as a first-class deliverable, and a named accountable owner.', 'intermediate'),
('devops', 'platform-engineering', 'intermediate', 'What does a Backstage Scorecard convert "is this service on the golden path" from?', '["From an automated check into a manual survey", "From a periodic manual survey into a live, queryable, per-service dashboard", "From a per-service question into an org-wide average with no per-service detail", "Scorecards have no effect on how adoption is measured"]', 1, 'Backstage Scorecards convert "which teams are actually on the golden path" from a periodic manual survey into a live, queryable dashboard -- making it possible to identify specifically which services are lagging and why, not just the aggregate adoption percentage.', 'intermediate'),
('devops', 'platform-engineering', 'intermediate', 'In the Crossplane Composition example, what does the platform team define once, versus what the requesting developer sees?', '["The developer sees the full Terraform configuration; the platform team sees nothing", "The platform team owns and versions the Composition (encoding cloud complexity, security defaults, tagging/compliance requirements); the developer sees a small, safe, opinionated PostgresDatabase request", "Both the developer and platform team interact with the exact same YAML file", "The Composition is defined by the developer per-request, not the platform team"]', 1, 'The Composition (owned and versioned by the platform team) encodes all the actual cloud-provider complexity, security defaults, and tagging/compliance requirements a raw Terraform apply would otherwise leave to the requesting developer to get right themselves -- the developer only ever sees a small, opinionated request.', 'advanced'),
('devops', 'platform-engineering', 'intermediate', 'What does the described service maturity model (Level 0 through Level 4) provide that a binary "on the golden path or not" metric cannot?', '["It provides exactly the same information as a binary metric, just relabeled", "A legible, incremental path forward for a team, and lets the platform team prioritize investment toward services stuck at a specific level rather than one undifferentiated bucket", "It removes the need for any adoption tracking at all", "It only applies to services with zero existing infrastructure"]', 1, 'A staged maturity model does two things a binary metric can''t: gives a team a legible, incremental path forward rather than an all-or-nothing migration, and lets the platform team prioritize investment toward services stuck at a specific level instead of treating "not fully adopted" as one bucket.', 'advanced'),
('devops', 'platform-engineering', 'intermediate', 'What is the practical effect of a platform team publishing an explicit internal SLA (e.g. database provisioning < 4 hours)?', '["It has no practical effect since SLAs are not enforceable internally", "A missed commitment becomes a visible, trackable signal the platform team is accountable to, rather than slow/unreliable service just looking like normal, unaddressed friction to consuming teams", "It removes the need for the platform team to actually meet any deadline", "It only applies to external customers, never internal developers"]', 1, 'Without a stated SLA, a slow or unreliable platform capability just looks like normal friction to dependent teams; with an explicit SLA, missed commitments become a visible, trackable signal the platform team is accountable to -- exactly like any other internal service-provider relationship.', 'advanced'),

-- ---------- devops/platform-engineering/advanced ----------
('devops', 'platform-engineering', 'advanced', 'What organizational pattern emerges once a single centralized platform team becomes its own bottleneck at large scale?', '["The platform team is simply given more headcount with no structural change", "A platform-of-platforms -- a central core platform team owning the foundational layer, with domain-specific platform teams (data, ML, mobile) building on top of that shared foundation", "Platform Engineering is abandoned entirely in favor of pure DevOps at that scale", "Every application team builds its own independent platform from scratch"]', 1, 'Past a certain scale, a single centralized platform team becomes its own bottleneck. The pattern that emerges is a platform-of-platforms -- a central core team owning identity, base infrastructure, and the portal itself, with domain-specific platform teams (data, ML, mobile) building on top of that shared foundation.', 'advanced'),
('devops', 'platform-engineering', 'advanced', 'What is the deciding factor typically cited for choosing to buy a managed IDP portal rather than self-hosting/building Backstage?', '["Buying is always cheaper than building at any organization size", "Whether the platform team''s genuine differentiated value is the portal experience itself, or the golden paths and Compositions built on top of it -- for most orgs, the actual value is in the latter", "Self-hosted Backstage cannot support any plugins", "Vendors do not allow any customization at all"]', 1, 'The deciding factor in practice is usually whether the platform team''s genuine differentiated, org-specific value is the portal experience itself or the golden paths/Compositions built on top of it -- for most orgs the real value is in the latter, favoring buying the portal layer.', 'advanced'),
('devops', 'platform-engineering', 'advanced', 'What distinguishes the "ivory tower platform team" anti-pattern from simple low adoption?', '["Ivory tower teams have low adoption numbers, identical to the low-adoption case", "Adoption numbers look healthy (often because usage is mandated), but developer satisfaction stays flat or declines, and the team is organizationally isolated with no embedded feedback loop or shared on-call exposure to the pain its tooling causes", "Ivory tower teams have no executive sponsorship at all, unlike low-adoption teams", "The two are the same anti-pattern described with different names"]', 1, 'The ivory-tower anti-pattern is subtler than low adoption: adoption numbers look healthy because usage is often mandated, but developer satisfaction stays flat or declines, and the team is organizationally isolated -- no embedded feedback loop, no shared exposure to the on-call pain its own tooling choices cause.', 'advanced'),
('devops', 'platform-engineering', 'advanced', 'What is described as the most common platform-team funding pattern at real organizational scale?', '["Fully centrally funded with no chargeback ever used", "A hybrid model -- core foundational capabilities centrally funded and mandatory, optional/premium capabilities chargeback-funded -- mirroring the platform-of-platforms split between mandatory core and optional domain capabilities", "Fully chargeback-funded with zero centrally-funded capabilities", "Platform teams are never funded; they operate as unpaid volunteer efforts"]', 1, 'The hybrid model -- core foundational capabilities centrally funded and mandatory, optional/premium capabilities chargeback-funded -- is described as the most common pattern at real scale, mirroring how the platform-of-platforms structure itself splits mandatory core from optional domain-specific capabilities.', 'advanced'),
('devops', 'platform-engineering', 'advanced', 'How does a chargeback funding model''s risk connect to the DORA-metrics-regression failure mode described elsewhere in this guide?', '["The two are entirely unrelated concepts in different domains", "A chargeback model that adds approval friction to provisioning is a structurally different mechanism (billing approval vs. pipeline gates) arriving at the same standardized-but-slower outcome as an overly rigid golden-path pipeline", "Chargeback models always improve DORA metrics with no downside", "DORA metrics do not apply to platform team funding decisions at all"]', 1, 'A chargeback model that adds approval friction to provisioning is a structurally different way of arriving at the same "standardized but slower" outcome that an overly rigid pipeline template produces -- the root cause category (added process cost without proportional benefit) is the same even though the specific mechanism differs.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
